// @ts-nocheck
import type { Pathfinder2eSpellDefinition } from './models'

export const PATHFINDER_2E_SPELL_DATA_4: Pathfinder2eSpellDefinition[] = [{"id":"pf2e.spell.marvelous-mount","name":"Marvelous Mount","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"one creature","area":null},"duration":{"text":"8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a Large fantastical creature to serve as a mount for the target. The mount is the target's minion, has a Speed of 40 feet, and can bear the target with any carried possessions. It can't carry any other creature. The mount uses the target's AC and saves, but it's destroyed if it takes more than 10 damage at one time, ending the spell.\n\nHeightened (3rd) The mount can walk on water, but it must end its turn on solid ground or sink.\n\nHeightened (4th) The mount has a Speed of 60 feet and can walk on water.\n\nHeightened (5th) The mount has a Speed of 60 feet and can walk on water. It also has a fly Speed of 60 feet, but it must end its turn on a surface or fall.\n\nHeightened (6th) The mount has a Speed and fly Speed of 80 feet.","source":{"provider":"PAIZO","sourceId":"WPKJOhEihhcIm2uQ","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.menacing-lament","name":"Menacing Lament","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["auditory","concentrate","emotion","focus","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You wail a dirge for your enemies. Enemies in the area are against your attacks and gain no benefits from flanking you for the duration.","source":{"provider":"PAIZO","sourceId":"6TudR1rDkxWMj1cv","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mental-map","name":"Mental Map","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You glean detailed information about a specific place visited by a creature directly from its mind, unless it fends you off with a Will save. The target can choose to fail the save.\nSuccess The target is unaffected.\n\nFailure You gain critical information about the place in question, granting you a +2 circumstance bonus to Survival checks while in the location and any skill checks to Recall Knowledge about the location for the next 24 hours.\n\nCritical Failure As failure, but you can erase all knowledge of the location from the target for 24 hours if desired.","source":{"provider":"PAIZO","sourceId":"PEGECeEtEmXEzwBT","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mimic-undead","name":"Mimic Undead","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"You're a living creature"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You take death and wrap it about you like a cloak-your colors wash out and your skin grows cold to the touch. Your heartbeat, breathing, and similar life functions become very difficult to detect. Senses such as lifesense detect you as undead unless a creature succeeds at a Perception check against the spell's DC, and on a failed check, they don't detect you at all if they only sense living creatures. Detection spells that specifically sense living creatures must succeed at a counteract check against mimic undead to detect you. You gain a +4 status bonus to Impersonate an undead but physically intact version of yourself and can add your level as your proficiency bonus even if you're untrained. You don't gain these benefits to Impersonate any other sort of undead. Mindless undead usually don't have a reason to even attempt the Perception check to notice your Impersonation unless you interact with them in some way.","source":{"provider":"PAIZO","sourceId":"xlRv8vCTHh1NeMpw","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mind-games","name":"Mind Games","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2},"cost":"3 gp game piece focus"},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You lock minds with the target, trying to mentally subdue them. The target must attempt a Will save. Each time you Sustain this Spell, the target attempts another Will save.\n\nCritical Success You are Stunned 1 and the spell ends.\n\nSuccess The target is unaffected.\n\nFailure The target is stunned 1.\n\nCritical Failure The target is Stunned 2.","source":{"provider":"PAIZO","sourceId":"29JyWqqZ0thCFr1C","book":"Pathfinder #169: Kindled Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mirror-image","name":"Mirror Image","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Three illusory images of you swirl about your space, potentially causing those who attack you to hit one of the images instead of you. Any attack that would hit you has a random chance of hitting one of your images instead of you. If all three images remain, there is a 1 in 4 chance of hitting you (1 on [[/r 1d4]]). With two images remaining, there is a 1 in 3 chance of hitting you (1-2 on [[/r 1d6]]). With only one image, the chances are 1 in 2 (1-3 on [[/r 1d6]]).\n\nOnce an image is hit, it is destroyed. If an attack roll fails to hit your AC but doesn't critically fail, it destroys an image but has no additional effect (even if the attack would normally have an effect on a failure). If an attack roll is a critical success and would hit one of the images, one of the images is destroyed and the attack roll becomes a success against you. Once all the images are destroyed, the spell ends.","source":{"provider":"PAIZO","sourceId":"j8vIoIEWElvpwkcI","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.mist","name":"Mist","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call forth a cloud of mist. All creatures within the mist become , and all creatures outside the mist become concealed to creatures within it. You can Dismiss the cloud.","source":{"provider":"PAIZO","sourceId":"9XHmC2JgTUIQ1CCm","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.noise-blast","name":"Noise Blast","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","sonic"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"2d10","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"A cacophonous noise blasts out, dealing 2d10 sonic damage. Each creature must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage.\n\nFailure The creature takes full damage and is for 1 round.\n\nCritical Failure The creature takes double damage, is deafened for 1 minute, and is Stunned 1.\n\nHeightened (+1) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"wzLkNU3AAqOSKFPR","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.oaken-resilience","name":"Oaken Resilience","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target's skin becomes tough, with a consistency like bark or wood. The target gains resistance 2 to bludgeoning and piercing damage and weakness 3 to fire. After the target takes fire damage, it can Dismiss the spell as a free action triggered by taking the damage; doing so doesn't reduce the fire damage the target was dealt.\n\nHeightened (+2) The resistances increase by 2, and the weakness increases by 3.","source":{"provider":"PAIZO","sourceId":"YWrfKetOqDwVFut7","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.oil-slicked-walls","name":"Oil-Slicked Walls","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"}},"targeting":{"range":{"kind":"NONE"},"target":"the outer walls of a settlement","area":{"shape":"EMANATION","feet":36960}},"duration":{"text":"1 week","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Warfare Lore (expert)","secondaryChecks":"Architecture Lore or Crafting","secondaryCasters":1},"description":"The outer walls are a city's first defense against invaders, and you want to make certain no attackers can climb over them. Upon successful completion of this ritual, the surfaces of a settlement's walls within the area are covered with a thin, slippery sheen that can't be washed away.\nCritical Success The oil covering the walls also coats any climber's hands. The DC for Athletics checks to Climb the affected walls increases by 10, and a creature who fails a check to climb also drops anything they are carrying.\n\nSuccess The DC for Athletics checks to Climb the affected walls increases by 5.\n\nFailure The ritual has no effect.\n\nCritical Failure Phantom oil constantly pools around your feet during times of stress. For 1 week, the first time each encounter that a primary or secondary caster takes an action to move, they must attempt a Reflex save or Acrobatics check to against the ritual's casting DC or fall . A caster can Step or without having to attempt a check or save.","source":{"provider":"PAIZO","sourceId":"bOf5WuLh6ZJloi7F","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.one-with-plants","name":"One with Plants","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","plant","polymorph","wood"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes or 8 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can either transform into a plant or merge with plant matter. While transformed, you can't move or affect anything outside the plant, but you can cast spells as long as they don't require line of effect beyond the plant. You can Dismiss this spell.\n\n- Merge with Plants The spell's duration is 10 minutes. While casting the spell, you must touch a plant with enough volume to fit you and your possessions or the spell is disrupted. While merged, you can hear, but not see, what's going on outside the plant. If the plant takes damage while you're inside it, you're expelled from the plant and take 10d6 damage. Magic passage expels you without dealing damage. The spell ends if you're ever outside the plant.\n\n- Turn into a Plant The spell's duration is 8 hours. You become a Large plant—typically a tree. Perception checks don't reveal your true nature, but a successful Nature or Survival check against your spell DC reveals that you appear to be a plant that is strangely new to the area. While in this form, you can observe everything around you, using your normal senses. As a plant, your AC is 20, and only status bonuses, status penalties, circumstance bonuses, and circumstance penalties affect you. Any successes and critical successes you roll on Reflex saves are failures","source":{"provider":"PAIZO","sourceId":"dileJ0Yxqg76LMvu","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.open-the-wall-of-ghosts","name":"Open the Wall of Ghosts","kind":"RITUAL","rank":2,"rarity":"RARE","traits":["consecration"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rice grains and incense worth 60 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":40},"target":"the Wall of Ghosts","area":null},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism or Religion (expert)","secondaryChecks":"Deception, Diplomacy, or Intimidation","secondaryCasters":3},"description":"","source":{"provider":"PAIZO","sourceId":"PvkEzzCaDT07DcJb","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.osseous-cage","name":"Osseous Cage","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"CUBE","feet":5}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a prison made of bone. Creatures in the space where you create the cage can attempt a Reflex save; if they fail or don't attempt the save, they're trapped within it. The spell automatically fails if the space contains a creature larger than the spell's area.\n\nA creature inside the cage is until it Escapes, uses an effect that can pass through solid objects, or destroys the cage. The cage has AC 10, Hardness 5, and 10 Hit Points, and it's immune to critical hits and precision damage.\n\nThe osseus cage provides lesser cover from attacks that pass through the cage, either from the outside to the inside or visa versa.\n\nHeightened (+2) The spell's area grows by 5 feet on aside and it's Hit Points increase by 20.","source":{"provider":"PAIZO","sourceId":"Cbwhd4m7qrRoRjot","book":"Pathfinder Wake the Dead #4","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pack-attack","name":"Pack Attack","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"you and 1 willing creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You and one other target gain an uncanny coordination that helps you take down foes. You and the other target flank any enemy to which you are both adjacent, whether or not you are on opposite sides of the enemy's space.\n\nHeightened (5th) The spell can target you and up to 4 willing creatures touched.","source":{"provider":"PAIZO","sourceId":"eW7DqGEvU50CDHqc","book":"Pathfinder #175: Broken Tusk Moon","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.paranoia","name":"Paranoia","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You cause the target to see all other creatures as dire threats. The target is stricken by intense paranoia toward all creatures around it and must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target believes everyone it sees is a potential threat. It becomes to all creatures to which it wasn't already hostile, even those that were previously allies. It treats no one as an ally. The spell ends after 1 round.\n\nFailure As success, but the effect lasts 1 minute.\n\nCritical Failure As failure, except the target believes that everyone it sees is a mortal enemy. It uses its reactions and free actions against everyone, regardless of whether they were previously its allies, as determined by the GM. It otherwise acts as rationally as it normally does and likely prefers to attack creatures that are actively attacking or hindering it over those leaving it alone.\n\nHeightened (6th) You can target up to 5 creatures.","source":{"provider":"PAIZO","sourceId":"Mkbq9xlAUxHUHyR2","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pave-ground","name":"Pave Ground","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":60}},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You even out the ground and push aside low obstacles. Non-magical difficult terrain or greater difficult terrain composed of earth, rubble, sand, and the like in the area becomes normal terrain. You can attempt a counteract check against magical difficult terrain and greater difficult terrain composed of earthen materials in the area, too, making it normal terrain for the duration if you succeed. The ground doesn't change quickly enough to cause anyone to lose footing, and it doesn't clear concealing features enough to make them non-concealing. At the GM's discretion, if you use this spell on \"ground\" that has no underlying surface to flatten and clear, such as ice on the surface of a lake, the spell fails.\n\nHeightened (4th) The area increases to a along the ground.\n\nHeightened (6th) The area increases to a along the ground.","source":{"provider":"PAIZO","sourceId":"mS3p6BR3LcG1WmHs","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.peaceful-rest","name":"Peaceful Rest","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 corpse","area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"The targeted corpse doesn't decay, nor can it be transformed into an undead. If the corpse is subject to a spell that requires the corpse to have died within a certain amount of time (for example, ), do not count the duration of peaceful rest against that time. This spell also prevents ordinary bugs and pests (such as maggots) from consuming the body.\n\nHeightened (5th) The spell's duration is unlimited, but the spell takes one more action to cast and requires a cost (embalming fluid worth 6 gp).","source":{"provider":"PAIZO","sourceId":"xRgU9rrhmGAgG4Rc","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.penumbral-disguise","name":"Penumbral Disguise","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","darkness","manipulate","shadow"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You wrap the target in shadows, granting it a +1 status bonus to Stealth checks to Hide while in dim light or darkness. In addition, the shadows mask the target's features. While the target is in dim light or darkness, other creatures must succeed at a action against the spell's DC to discern details about its appearance. For example, without using Seek, other creatures can determine the target's general shape (such as humanoid), but they must Seek to determine the target's precise appearance. Creatures with darkvision can still see the target and its features normally. The target's normal appearance is revealed in bright light.\nHeightened (4th) The status bonus is +2. Creatures with darkvision can no longer discern details about the target while the target is in dim light or darkness without Seeking, though creatures with greater darkvision can still determine these details.\n\nHeightened (6th) As 4th rank, except the status bonus is +3, and creatures without darkvision can't determine even general details about the target while the target is in dim light or darkness unless they successfully Seek the target; these creatures see a vague shadow instead. Even on a successful Seek, they only determine general features, though they can see details on a critical success.\n\nHeightened (8th) As 6th rank, except the status bonus is +4, and even creatures with greater darkvision must Seek to discern details about the target while the target is in dim light or darkness.","source":{"provider":"PAIZO","sourceId":"QZ7OHptO1xnwaruq","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.perfect-strike","name":"Perfect Strike","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","fortune"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You miss a Strike with an unarmed attack.\n\nYou call upon insight from your training to recover accuracy. Reroll the missed attack roll and keep the new result.","source":{"provider":"PAIZO","sourceId":"GQopUYTuhmtb7WMG","book":"Pathfinder Lost Omens World Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.persistent-servant","name":"Persistent Servant","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":60}},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call forth an unseen servant and task it to perform a specific chore repeatedly. Choose a basic instruction, such as sweeping the floor, or picking up all objects from the floor and putting them in a designated bin. The servant performs the task over and over again throughout the duration, though it can't ever leave the spell's area.\n\nThe servant isn't a minion, and you don't need to Sustain the Spell in order for it to continue to act. However, it acts on its own time, and thus can't accomplish anything useful during an encounter, even if an encounter happens within the spell's range.\n\nTasks that rely on timing, discretion, or significant manual dexterity are doomed to failure. For instance, a servant tasked to pick objects off the floor won't discriminate between trash, misplaced treasure, or objects that are supposed to be on the floor, like a mousetrap.","source":{"provider":"PAIZO","sourceId":"qCmihBL0G0G5ExPF","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.phantasmal-treasure","name":"Phantasmal Treasure","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","emotion","illusion","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 living creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A phantasmal image of the most precious thing imaginable to the target appears in a location of your choice within the spell's range. Only the spell's target can see the treasure, though you can see the vague shape of the treasure-be it a pile of items, a deific avatar, or a cherished loved one or hero. The target's response to the treasure is based on the outcome of the target's Will save.\nCritical Success The target is unaffected.\n\nSuccess The target becomes with the treasure, and the duration is until the end of its turn. The target can also try to disbelieve the illusion if it touches the treasure, Seeks to examine it, or speaks to it if the illusion appears to be a person or the like. If the target disbelieves the illusion, the spell ends.\n\nFailure As success, but the duration is 1 minute.\n\nCritical Failure As success, but the duration is 1 minute. The target finds the treasure so appealing that until the spell ends, it must spend each action focused on it. This can include moving toward the treasure if the target isn't next to it, and Interacting with the treasure if the target is next to it. (If the illusion appears to be a person or the like, the target can also Interact to converse with it.)","source":{"provider":"PAIZO","sourceId":"L0GoJpHxSD0wRY5k","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.phantom-crowd","name":"Phantom Crowd","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","visual"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":5}},"duration":{"text":"10 minutes","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A tightly packed crowd of humanoids appropriate to the area appear, facing you and agreeing loudly with anything you say. A creature that touches a member of the crowd or makes a Seek action to examine the crowd can attempt to disbelieve your illusion. The crowd is difficult terrain for anyone who hasn't disbelieved the illusion.\n\nWhen you spend 1 or more actions to cast a composition spell or to perform an activity that includes a Performance check, you can also Sustain this Spell as part of that action.\n\nHeightened (+1) The crowd occupies an additional 10-foot square in range. The additional square doesn't need to be adjacent to any other square created by the spell. It can overlap, but there's no additional effect in the overlapped squares.","source":{"provider":"PAIZO","sourceId":"WfINystwLv9ohYpS","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.phantom-ship","name":"Phantom Ship","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":["teleportation"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"pearls or other gems worth a total value of 50 gp"},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 ship no more than 175 feet long","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Occultism (expert)","secondaryChecks":"Sailing Lore or Survival","secondaryCasters":2},"description":"You create a link between a ship and an undead member of its crew to temporarily make the ship, and its passengers and crew, as incorporeal as ghosts. The targeted ship must be intact and on or near the surface of some water, and an undead who was a member of the ship's crew in life must be present for the entire ritual.\n\nCritical Success The ship and all creatures aboard it become incorporeal for 1 hour. During this time, the ship can sail at its top speed in any heading chosen by the primary caster, regardless of the winds. The ship can pass through any corporeal obstacles in its path (such as rocks or other vessels), but it must remain in contact with water or the ritual's effects end prematurely. Any skill checks required to sail the ship through rough weather gain a +2 status bonus. A creature that disembarks the ship while the ritual is in effect becomes corporeal again.\n\nSuccess As critical success, but the status bonus to skill checks is only +1.\n\nFailure The ritual has no effect.\n\nCritical Failure The ship, but not its passengers or crew, becomes incorporeal for 10 minutes, usually resulting in the passengers and crew falling through the ship into the waters below. If the ship was already sailing, it continues in its current direction at its current speed.","source":{"provider":"PAIZO","sourceId":"oOFilBgsXTVIbJpN","book":"Pathfinder Adventure Path: Gatewalkers","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.power-of-the-beasts","name":"Power of the Beasts","kind":"RITUAL","rank":2,"rarity":"RARE","traits":["trial"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"bones, teeth, or claws of beasts worth 150 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Athletics (expert)","secondaryChecks":"Cooking Lore, Crafting, Religion","secondaryCasters":1},"description":"To simply kill the magical beasts who populate Tian Xia is needless and wasteful. The gods reward a hunter who seeks to truly understand their prey, approaching the creatures on their own level and seeking to gain their strength. Powdering the bones of strong beasts, for use in a soup or wine, is often the first step in the process of capturing part of their power.\n\nUsing weapons is anathema to this ritual and immediately ends its benefits. If the ritual is ended in this way, you must conduct an ritual before attempting this ritual again.\n\nCritical Success As success, except you can defeat three enemies that are only one size larger than you instead.\n\nSuccess The power begins to take root. Once you've defeated an enemy two or more sizes larger than you in single combat, you gain the feat.\n\nFailure You drink the soup or wine, but the understanding eludes you.\n\nCritical Failure The drink contains shards of bone you didn't grind down properly. You're Sickened 2 for 1 week, during which the condition can't be reduced.","source":{"provider":"PAIZO","sourceId":"otdzpPYzWMJt76Rh","book":"Pathfinder Lost Omens Tian Xia World Guide","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.propulsive-breeze","name":"Propulsive Breeze","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["air","manipulate","move"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"the triggering creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An ally in range Strides or Leaps.\n\nYou create a current of wind at your ally's back, propelling their movement. When your ally's Stride or ends, the current propels them an additional 15 feet in the same direction as the last 5 feet of their Stride or Leap.","source":{"provider":"PAIZO","sourceId":"jlOAXuIOM3YxZKmn","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.purify-soul-path","name":"Purify Soul Path","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare incense and offering worth a total of 10 gp x your level"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Religion (trained)","secondaryCasters":0},"description":"You delve inward, spending extensive time contemplating the purity of your own soul and the actions of your past. If you aren't truly penitent, the outcome is always a critical failure.\n\nCritical Success You reconcile your misdeeds with your soul path, removing your soulforged corruption. The corruption flaw from your armament no longer affects you. Before your reconciliation is complete, you must perform a special quest or other task in accord with your soul path. If completed during downtime, this task should take no less than 1 week. For 1 month, you receive divine insight just before performing an act that would be anathema to your soul path.\n\nSuccess As critical success, but you gain no special insight regarding its subsequent actions.\n\nFailure You don't reconcile and must continue to meditate and redress your misdeeds. Any future purify soul path rituals for the same misdeeds cost half as much and gain a +4 circumstance bonus to the primary check.\n\nHeightened (+1) Increase the maximum target level by 2 and the base cost by 10 gp.","source":{"provider":"PAIZO","sourceId":"66xBcxqzYcpbItBU","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.pyrefowl-rebuke","name":"Pyrefowl Rebuke","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["fire","manipulate","move"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"labXcsiI8H8LkSER","formula":"1d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"labXcsiI8H8LkSER":"1d6"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Trigger A creature within 10 feet of you Strikes and deals damage to you.\nFiery wings briefly envelop your arms, and with a swift wingbeat, you flutter away from your attacker in a shower of searing sparks. You deal 1d6 fire damage to the triggering creature, with a basic Reflex save, and Fly up to 10 feet in a straight line directly away from it. If the creature critically fails its saving throw, your movement does not provoke reactions from it, and it's until the end of its next turn.\nHeightened (+2) The damage increases by 1d6, and the maximum distance you can Fly increases by 5 feet.","source":{"provider":"PAIZO","sourceId":"xnh2NBOGs4hcH9B3","book":"Pathfinder #216: The Acropolis Pyre","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.quench","name":"Quench","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":true},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"4d8","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d8"},"areaFeet":0},"counteraction":true,"ritual":null,"description":"You cause the air in the area to become supersaturated with water vapor. Non-magical fires within the area are automatically extinguished. Fire creatures within the area take 4d8 damage (basic Fortitude save). Choose one magical fire, fire spell, or fire item in the area and attempt to counteract it. If you succeed against an item, the item loses its fire properties for 10 minutes (for instance, a +1 Flaming Longsword would become a +1 Longsword). If the target is an artifact or similarly powerful item, you automatically fail to counteract it.\n\nThe first time each round you Sustain this spell, you can move the area of vapor anywhere within range, but the only effect when you do so is to automatically extinguish non-magical fires.\n\nIf you have the Counterspell reaction, you can use quench to counter any spell with the fire trait instead of needing to have the triggering fire spell prepared or in your repertoire.\nHeightened (+1) Increase the damage to fire creatures by 2d8.","source":{"provider":"PAIZO","sourceId":"02J0rDTk37KN2sjt","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.radiant-field","name":"Radiant Field","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","light","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an area of bright light. Creatures with that are by radiant field and remain in the area must attempt a Fortitude save at the start of their turns. On a failure, a creature remains blinded for 1 round; this is an incapacitation effect.\n\nThis spell also suppresses magical darkness of your radiant field spell's rank or lower.\nHeightened (4th) Creatures seen through the area are to creatures outside the area. Creatures with light blindness can continue to be blinded by the field as long as the field is visible, even when outside of the field.","source":{"provider":"PAIZO","sourceId":"v3vFzGazNSFEDdRB","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rallying-anthem","name":"Rallying Anthem","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["bard","cantrip","composition","concentrate","emotion","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":60}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your song moves allies to protect themselves more effectively. You and all allies in the area gain a +1 status bonus to AC and saving throws, as well as resistance equal to half the spell's rank to physical damage.","source":{"provider":"PAIZO","sourceId":"bH0kPuf7UKxRvi2P","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rapid-adaptation","name":"Rapid Adaptation","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"your companion or eidolon","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You flood the target with energy from the terrain around it, compressing centuries of evolution into a single moment. The target gains one of the following natural adaptations based on the surrounding environment.\n- Aquatic The target gains a swim Speed equal to its land Speed. If it already had a swim Speed, it gains a +10-foot status bonus to its swim Speed.\n- Arctic The target isn't affected by severe or extreme cold, and when it rolls a success on an Acrobatics check to Balance on ice and snow, it gets a critical success instead.\n- Desert The target isn't affected by severe or extreme heat, and when it rolls a success on an Acrobatics check to Balance on sand, it gets a critical success instead.\n- Forest The target gains scent as an imprecise sense with a range of 30 feet.\n- Mountain The target isn't when Climbing, and when it rolls a success on an Acrobatics check to Balance on rubble, it gets a critical success instead.\n- Plains The target gains a +10-foot status bonus to its land Speed.\n- Underground The target gains darkvision.","source":{"provider":"PAIZO","sourceId":"fTK6ysisGhy3hRvz","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.reapers-lantern","name":"Reaper's Lantern","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["aura","concentrate","death","light","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":5}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call forth a ghostly lantern that guides the living toward death and the undead toward true death. It sheds bright light in the spell's area and dim light to twice that area. The lantern is insubstantial and floats near you, suspended from an ephemeral, skeletal hand. Living creatures and undead in the area when you Cast the Spell, or that enter the area later, must attempt Fortitude saves. Living creatures that fail their Fortitude saves gain only half the normal benefit from healing effects while within the area. Undead targets that fail their Fortitude saves become Enfeebled 1 while within the area. Once a creature attempts a save against reaper's lantern, it uses the same outcome if it leaves the area and enters it again.\n\nOnce per turn, starting on the round after you cast reaper's lantern, you can Sustain the spell to increase the emanation's radius by 5 feet. When you do so, you force creatures in the area that haven't yet attempted a save against reaper's lantern to attempt one.","source":{"provider":"PAIZO","sourceId":"dxOF7d5kAWusLKWF","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.regale-the-lost-ones","name":"Regale the Lost Ones","kind":"RITUAL","rank":2,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"4 hours"},"cost":"fees for opera actors, their meals, facial paint, costumes, incense, and offerings of alcohol, tobacco, and food for the lost ones with a total value of 2 gp × the spell rank × the settlement's level"},"targeting":{"range":{"kind":"NONE"},"target":"a settlement with a level equal to or lower than twice the ritual's level","area":null},"duration":{"text":"1 year","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Performance (expert)","secondaryChecks":"Acrobatics, Occultism, or Religion","secondaryCasters":3},"description":"Autumn's shorter days herald an increase in hauntings, which only intensify during winter's cold, dark nights. As fall draws to a close, some of Shenmen's villages hire or set up Tian opera troupes to enact regale the lost ones rituals, where they perform dramas drawn from literary classics and historical events that incorporate acting, music, acrobatics, and martial arts.\n\nThese ritual performances fulfill a dual purpose; not only do they bring cheer to the living, but they also entertain and placate the \"lost ones\"—a euphemism for ghosts and other spirits—and seek to reduce the likelihood of attacks from such entities. Performing this ritual during the season of fall reduces the DCs of the ritual's skill checks by 2.\n\nIf the ritual is successful, sentient undead and other spirits become less hostile, allowing villagers to focus their efforts on dealing with mindless undead and other more physical threats. This ritual can only be attempted once per year per settlement; additional attempts to regale the lost ones in the same settlement automatically result in a critical failure.\nCritical Success Haunts and undead in the settlement that are level 3 or lower become easier to defeat. Reduce all Disable DCs for affected haunts in the settlement by 2, and all affected undead within the settlement begin combat Frightened 1. If the PCs perform this ritual during Act 2 or Act 3, they gain 3 Hope Points.\n\nSuccess Haunts in the settlement that are level 3 or lower become easier to notice and defeat. Reduce all Disable DCs for affected haunts in the settlement by 1. If the PCs perform this ritual during Act 2 or Act 3, they gain 1 Hope Point.\n\nFailure The ritual has no effect.\n\nCritical Failure Haunts and undead in the settlement that are level 3 or lower become more difficult to notice and defeat. Increase all Disable DCs for affected haunts in the settlement by 2, and all affected undead within the settlement gain the elite adjustment. If the PCs perform this ritual during Act 2 or Act 3, they lose 3 Hope Points.\nHeightened (+1) Increase the level of affected haunts and undead by 2.","source":{"provider":"PAIZO","sourceId":"FQZaQXiKtHdVjSc5","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.resist-energy","name":"Resist Energy","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"A shield of elemental energy protects a creature against one type of energy damage. Choose acid, cold, electricity, fire, or sonic damage. The target and its gear gain resistance 5 against the damage type you chose.\n\nHeightened (4th) The resistance increases to 10, and you can target up to two creatures.\n\nHeightened (7th) The resistance increases to 15, and you can target up to five creatures.","source":{"provider":"PAIZO","sourceId":"Fr58LDSrbndgld9n","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.restoration","name":"Restoration","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","healing","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Restorative magic counters the effects of toxins or conditions that prevent a creature from functioning at its best. When you cast restoration, choose to either reduce a condition or lessen the effect of a toxin. A creature can benefit from only one restoration spell each day, and it can't benefit from restoration more than once to reduce the stage of the same exposure to a given toxin.\n\n- Lessen a Toxin Reduce the stage of one toxin the target suffers from by one stage. This can't reduce the stage below stage 1 or cure the affliction.\n\n- Reduce a Condition Reduce the value of the target's , , or condition by 2. You can instead reduce two of the listed conditions by 1 each.\n\nHeightened (4th) Add to the list of conditions you can reduce. When you lessen a toxin, reduce the stage by two. You also gain a third option that allows you to reduce the target's value by 1. You can't use this to reduce a permanent Doomed condition.\n\nHeightened (6th) As the 4th-rank restoration, but you can reduce a permanent Doomed condition if you add a spellcasting action and a material component while Casting the Spell, during which you provide 100 gp worth of diamond dust as a cost.","source":{"provider":"PAIZO","sourceId":"SnaLVgxZ9ryUFmUr","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.revealing-light","name":"Revealing Light","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","light","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":10}},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A wave of magical light washes over the area. You choose the appearance of the light, such as colorful, heatless flames or sparkling motes. A creature affected by revealing light is . If the creature was , it becomes instead. If the creature was already concealed for any other reason, it is no longer concealed.\n\nCritical Success The target is unaffected.\n\nSuccess The light affects the creature for 2 rounds.\n\nFailure The light affects the creature for 1 minute.\n\nCritical Failure The light affects the creature for 10 minutes.","source":{"provider":"PAIZO","sourceId":"0qaqksrGGDj74HXE","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rime-slick","name":"Rime Slick","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["cold","concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d4","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You call down a chill wind. When you Cast this Spell, you deal 2d4 cold damage to each creature in the area (basic Reflex save). If a creature in the area critically fails its Reflex save and was standing, it also falls .\n\nYou also create a layer of ice on all surfaces in the area, which become difficult terrain. Unattended objects in the area become slick with ice, and picking them up requires a successful Reflex save or Acrobatics check against your spell DC. The ice melts on any object that takes fire damage as well as in any square included in the area of a higher-rank spell or effect with the fire trait.\n\nHeightened (5th) The damage increases to 8d4 cold damage and the area is a 30-foot burst.\n\nHeightened (8th) The damage increases to 14d4 cold damage and the area is a 60-foot burst.","source":{"provider":"PAIZO","sourceId":"Popa5umI3H33levx","book":"Pathfinder #151: The Show Must Go On","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION"]}},{"id":"pf2e.spell.rite-of-cleansing-flame","name":"Rite of Cleansing Flame","kind":"RITUAL","rank":2,"rarity":"RARE","traits":["consecration","fire"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"8 hours"},"cost":"rare incense worth 300 gp and 1 Mythic Point from the primary caster"},"targeting":{"range":{"kind":"NONE"},"target":"The city-state of Pol-Bailax","area":null},"duration":{"text":"instantaneous","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"DC 20 Religion or Occultism","secondaryChecks":"DC 18 Acrobatics, Nature, or Performance","secondaryCasters":3},"description":"Drawing on the latent power suffused within Pol-Bailax by its phoenix patron, you and the secondary casters send an ephemeral rush of cleansing energy through the city. Those within the area when the ritual successfully concludes are immediately cured of all detrimental emotion and mental effects; affected creatures cease any current hostilities as though they'd failed a save against calm, though this doesn't control their future actions.\nCritical Success The ritual's power lingers within its casters, granting them a +1 status bonus against emotion and mental effects for 1 month.\n\nSuccess The ritual succeeds.\n\nFailure The ritual has its intended effect, but alters its casters' forms as they fail to contain the phoenix's power. All casters develop a feature reminiscent of a phoenix, such as feathers, glowing red eyes, or talons, and gain weakness 5 to cold and unholy. This is a curse effect.\n\nCritical Failure As failure, but each caster must succeed at a fortitude save or be permanently Drained 1 for as long as they have the phoenix features.","source":{"provider":"PAIZO","sourceId":"KwDyrUIlnOrpdxYi","book":"Pathfinder #216: The Acropolis Pyre","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rite-of-repatriation","name":"Rite of Repatriation","kind":"RITUAL","rank":2,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"2 hours"},"cost":"rare incense, offerings, or charitable donations to the rightful owners worth a total value of 5 gp × the target's level (minimum 1 gp)"},"targeting":{"range":{"kind":"DISTANCE","feet":15},"target":"1 object of up to 4th level","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{}},"counteraction":false,"ritual":{"primaryCheck":"Occultism (trained) or Religion (trained)","secondaryChecks":"Occultism or Religion (whichever is used for the primary check); Diplomacy, Performance, Society, or a Lore corresponding to the rightful owners","secondaryCasters":0},"description":"You call upon and apologize to local spirits as you ritually return a culturally important object to its creators, heirs, or resting place. If the spirits accept, they repair some of any damage the object might have sustained since it was last in their possession. Learning about the item's significance and its rightful owners' history often makes this ritual easier to perform, as does performing significant deeds to repair past harm. The deeds or depth of knowledge required is subject to the GM's discretion. Typically, this gives the primary check a hard DC (rather than very hard) for a level that's twice the spell's rank, and it gives the secondary checks an easy DC (rather than standard).\n\nSuccess The ritual restores up to 5 Hit Points per spell rank to the object, potentially removing the broken condition if this repairs it past the item's Broken Threshold; the ritual does not replace lost pieces, not does it repair an object that's been destroyed. This restores only Hit Points lost since the item was last in its rightful owners' possession. In addition, the primary caster attempts a counteract check against one curse, spell effect, creature occupying the item with a possession effect, or similar effect that began affecting the item since it was last in its rightful owners' possession. This functions as or . If the primary caster successfully counteracts a possession effect, the possessing creature either manifests adjacent to the item (if incorporeal) or returns to its body (if not).\n\nFailure As success, but the spirits lambast the casters for letting the item become lost in the first place, making the casters Doomed 1.\n\nCritical Failure The ritual fails, and the casters become doomed 1.\n\nHeightened (+1) Increase the maximum target level by 2, the cast time by 1 hour, and the base cost by 10 gp","source":{"provider":"PAIZO","sourceId":"w00PBRjENqJa7Vxu","book":"Pathfinder #193: Mantle of Gold","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.rubble-step","name":"Rubble Step","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target leaves behind a trail of shifting rubble that typically consists of stones, but you could choose another earthen material, such as loose sand or soil. For 2 rounds, when the target willingly moves out of a space, and if the target is in contact with the ground, the ground in that space becomes difficult terrain. The difficult terrain remains for the spell's duration.\n\nHeightened (4th) The target leaves difficult terrain behind for 1 minute instead of two rounds, and the spell's duration is 10 minutes.","source":{"provider":"PAIZO","sourceId":"FFBYPZEmAQoll09t","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sea-surge","name":"Sea Surge","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the start of your next turn","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"yRdlETS4TihX3ekq","formula":"3d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You slap or stomp on a nearby solid or liquid surface, sending a surge of water rushing away from you. The water forms a flat, 5-foot-thick, 10-foot-high wall of water between 5 and 15 feet wide (you decide). It moves 60 feet in a direction of your choice along the struck surface, extinguishing all non-magical fires, carrying along unattended objects of 1 Bulk or less, and pushing larger objects. The wave moves another 60 feet in the same direction at the start of your next turn, then vanishes. Large or smaller creatures in the area or that enter the area the wave moves through must attempt a Fortitude save.\n\nSuccess The creature is unaffected.\n\nFailure The creature is knocked . If the creature was Swimming, it gets a critical failure instead.\n\nCritical Failure The creature is pushed 20 feet in the wave's direction, is knocked Prone, and takes 3d6 bludgeoning damage.","source":{"provider":"PAIZO","sourceId":"cf7Jkm39uEjUFtHt","book":"Pathfinder #151: The Show Must Go On","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.see-the-unseen","name":"See the Unseen","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","revelation"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your gaze pierces through illusions and finds creatures and spirits. You can see invisible creatures as though they weren't invisible, although their features are blurred, making them and difficult to identify. You can also see incorporeal creatures, like ghosts, phased through an object from within 10 feet of an object's surface as blurry shapes seen through those objects. Subtler clues also grant you a +2 status bonus to checks you make to disbelieve illusions.\n\nHeightened (5th) This spell has a duration of 8 hours.","source":{"provider":"PAIZO","sourceId":"jwK43yKsHTkJQvQ9","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shadow-zombie","name":"Shadow Zombie","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate","shadow"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 zombie of level 1 or lower","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You cast a shadow over the target zombie, briefly turning it into shadowy vapor and controlling its movement. While in this vaporous state, the zombie is a minion under your control, gains resistance 8 to physical damage, and is immune to precision damage. It can't cast spells, activate items, or use actions that have the attack or manipulate traits. It gains a fly Speed of 10 feet and can slip through tiny cracks. If the target is already your minion when you cast the spell, it doesn't get a saving throw and becomes vaporous for 10 minutes. If the target is not your minion, it can attempt a Will save to resist the spell. If it's already under someone else's command, the controlling creature also rolls a Will save, and the zombie uses the better result.\n\nCritical Success The target is unaffected and is temporarily immune for 24 hours.\n\nSuccess The target is unaffected.\n\nFailure The target becomes your shadowy minion for 1 minute.\n\nCritical Failure As failure, but for 10 minutes.\n\nHeightened (4th) You can target a zombie of level 5 or lower.","source":{"provider":"PAIZO","sourceId":"4Gl3WSUqYjVVIsOg","book":"Pathfinder #181: Zombie Feast","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shape-wood","name":"Shape Wood","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"an unworked piece of wood up to 20 cubic feet in volume","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shape the wood into a rough shape of your choice. The shaping power is too crude to produce with intricate parts, fine details, moving pieces, or the like. You cannot use this spell to enhance the value of the wooden object you are shaping.","source":{"provider":"PAIZO","sourceId":"CXICME10TkEJxz0P","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.share-life","name":"Share Life","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You forge a temporary link between the target's life essence and your own. The target takes half damage from all effects that deal Hit Point damage, and you take the remainder of the damage. When you take damage through this link, you don't apply any resistances, weaknesses, or other abilities you have to that damage; you simply take that amount of damage. The spell ends if the target is ever more than 30 feet away from you. If either you or the target is reduced to 0 Hit Points, any damage from this spell is resolved and then the spell ends.","source":{"provider":"PAIZO","sourceId":"d7Lwx6KAs47MtF0q","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.shatter","name":"Shatter","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","sonic"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 unattended object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d10","damageType":"sonic","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"}},"counteraction":false,"ritual":null,"description":"A high-frequency sonic attack shatters a nearby object. You deal 2d10 sonic damage to the object, ignoring the object's Hardness if it is 4 or lower.\n\nHeightened (+1) The damage increases by 1d10, and the Hardness the spell ignores increases by 2.","source":{"provider":"PAIZO","sourceId":"1xbFBQDRs0hT5xZ9","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.shining-starlight-attack","name":"Shining Starlight Attack","kind":"SPELL","rank":2,"rarity":"RARE","traits":["concentrate","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d10","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"}},"counteraction":false,"ritual":null,"description":"Area varies (see below)\nYou brandish your sentinel weapon, summoning the image of your constellation above your head. The constellation then releases a powerful blast that deals 2d10 damage to all enemies in either a or , with a basic save against your arcane spell DC. Enemies that critically fail are until the start of your next turn. The damage type, traits, area, and saving throw are determined by your zodiac constellation (see below).\nHeightened (+1) The damage increases by 1d10.\nConstellationAttack (Area, Save, Damage Type; Traits)\nUnderworld DragonVolcanic vents (line, Reflex, fire)\nOgreWild club swing (cone, Fortitude, bludgeoning)\nSwordswomanFalling blades of light (line, Reflex, piercing)\nForest DragonSwarm of insects (cone, Fortitude, poison)\nSea DragonPressurized seawater (line, Reflex, piercing; water trait)\nBlossomStorming petals and pollen (line, Fortitude; poison, plant, wood)\nSwallowWing gust (cone, Reflex, slashing; air)\nDogA biting dog (line, Reflex, slashing)\nOxA trampling ox (line, Reflex, bludgeoning)\nSky DragonDraconic lightning (line, Reflex, electricity)\nSovereign DragonPsychic roar (cone, Will, mental)\nArcherHail of silver arrows (piercing, cone, Reflex)","source":{"provider":"PAIZO","sourceId":"yuhhRjqBzFgkKYrq","book":"Pathfinder Lost Omens Tian Xia Character Guide","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.shrink","name":"Shrink","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature","area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You warp space to make a creature smaller. The target shrinks to become Tiny in size. Its equipment shrinks with it but returns to its original size if removed. The creature's reach changes to 0 feet. This spell has no effect on a Tiny creature.\n\nHeightened (6th) The spell can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"PjhUmyKnq6K5uDby","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.silence","name":"Silence","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["illusion","manipulate","subtle"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target makes no sound, preventing creatures from noticing it using hearing alone. The target can't use sonic attacks, nor can it use actions with the auditory trait. This prevents it from casting spells due to the magical words involved in casting, with the exception of subtle spells.\n\nHeightened (4th) The spell creates an aura in a 10-foot emanation around the touched creature, silencing all sound in or passing through it. While within the aura, creatures are subject to the same effects as the target. Depending upon the position of the effect, a creature might notice the lack of sound reaching it (blocking off the noise coming from a party, for example).","source":{"provider":"PAIZO","sourceId":"gIdDLrbswTV3OBJy","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.slough-skin","name":"Slough Skin","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You continually and harmlessly slough off the top layer of your skin while new skin regenerates immediately, quickly moving damaging substances away from your body. The flat check to remove persistent damage from effects that coat your skin (such as most persistent acid damage) is reduced to 5, and you gain a +2 status bonus to your initial save against contact poison (but not to further saves since, by that point, the toxin has already entered your system).\n\nIf you're affected by an effect other than persistent damage that depends on continuous contact with your skin, and if that effect allows a saving throw, you receive a new saving throw against that effect at the end of each turn when you attempt your flat checks against persistent damage, and you also receive a +2 status bonus to those saving throws.\n\nWhile affected by this spell, your continually shedding skin makes you much easier to . Anyone Tracking you gains a +2 circumstance bonus to do so, and you can't Hide Your Tracks.","source":{"provider":"PAIZO","sourceId":"X3dYByf3YmkcdwG0","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sonata-span","name":"Sonata Span","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["auditory","concentrate","manipulate","sonic"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":30}},"duration":{"text":"","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"By playing a brief tune on an instrument or in song, you cause the notes of the melody to physically manifest into a shimmering, translucent path. This path doesn't need to be over solid ground and can tilt up or down diagonally up to 45 degrees, but it must be a straight, 5-foot-wide line. It can support as many creatures as can physically fit on the bridge.","source":{"provider":"PAIZO","sourceId":"Yv3AFIO55FONQYMH","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.soothing-mist","name":"Soothing Mist","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","healing","manipulate","ranger","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing living creature or 1 undead creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"2d8","damageType":"vitality","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You call forth a magical mist that envelops a creature. The mist restores 2d8 Hit Points to a target living creature and ends one source of persistent acid, bleed, fire, poison, or void damage affecting it. If the creature is taking persistent damage from multiple sources, you select which one is removed. Against an undead target, you deal 2d8 vitality damage (basic Fortitude save); if it fails the save, it also takes (@item.rank)[persistent,vitality] damage.\n\nHeightened (+1) The amount of healing (or damage to an undead target) increases by 1d8, and the persistent vitality damage to an undead creature increases by 1.","source":{"provider":"PAIZO","sourceId":"RGBZrVRIEDb2G48h","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.sound-body","name":"Sound Body","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","healing","manipulate","vitality"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You send a surge of healing energy to restore the target's body. Attempt to counteract an effect of your choice imposing one of these conditions on the target: , , , , or . If you didn't counteract the effect, but you would have if its counteract rank were 2 lower, instead suppress the effect until the beginning of your next turn. The effect's duration doesn't elapse while it's suppressed.\n\nThis spell can't counteract or suppress curses, diseases, or conditions that are part of the target's normal state.\nHeightened (4th) Add and to the list of conditions.\n\nHeightened (6th) As 4th rank, plus add .\n\nHeightened (8th) As 4th rank, plus add petrified and .","source":{"provider":"PAIZO","sourceId":"Et8RSCLx8w7uOLvo","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.speak-with-animals","name":"Speak with Animals","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You can ask questions of, receive answers from, and use the Diplomacy skill with animals. The spell doesn't make them more friendly than normal. Cunning animals are likely to be terse and evasive, while less intelligent ones often make inane comments.","source":{"provider":"PAIZO","sourceId":"BBvV7qoXGdw09q1C","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spirit-of-the-beast","name":"Spirit of the Beast","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","focus","morph"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"your animal companion","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You bring out the spirit of another animal that lives within your companion. Its body morphs slightly to take on an aspect of the animal you choose to have it emulate—for example, it might grow a pair of horns if the spirit is a bull or a tail if the spirit is a monkey. When you Cast this Spell, select from one of the following aspects.\n\n- Aspect of Might: Your companion gains a +1 status bonus to Athletics checks, Intimidation checks to , and Fortitude saves.\n\n- Aspect of Swiftness: Your companion gains a +1 status bonus to Acrobatics checks, Stealth checks to Hide or , and Reflex saves.\n\n- Aspect of Insight: Your companion gains a +1 status bonus to Perception checks to , Survival checks to Sense Direction or , and Will saves.\n\nHeightened (5th) The status bonuses increase to +2.\n\nHeightened (8th) The status bonuses increase to +3.","source":{"provider":"PAIZO","sourceId":"wgAsL86ji5hulh7x","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spirit-sense","name":"Spirit Sense","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","detection","manipulate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You open your mind to the metaphysical, enabling you to sense nearby spirits. Even if you aren't Searching, you get a check to find haunts and spirits in the area. You gain a +1 status bonus to the following checks regarding haunts or spirits: Perception checks to , attempts to Recall Knowledge, skill checks to determine the reason for their existence, and skill checks to disable a haunt. You also gain a +1 status bonus to AC and saving throws against haunts and spirits.\nHeightened (6th) The spell's duration lasts until the next time you make your daily preparations.","source":{"provider":"PAIZO","sourceId":"3ehSrqTAm7IPqbIZ","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.spiritual-armament","name":"Spiritual Armament","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["attack","concentrate","manipulate","sanctified","spirit"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"0Uok2pip94aNbBFd","formula":"2d8","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0Uok2pip94aNbBFd":"1d8"}},"counteraction":false,"ritual":null,"description":"You create a ghostly, magical echo of one weapon you're wielding or wearing and fling it. Attempt a spell attack roll against the target's AC, dealing 2d8 damage on a hit (or double damage on a critical hit). The damage type is the same as the chosen weapon (or any of its types for a versatile weapon). The attack deals spirit damage instead if that would be more detrimental to the creature (as determined by the GM). This attack uses and contributes to your multiple attack penalty. After the attack, the weapon returns to your side. If you sanctify the spell, the attacks are sanctified as well. Each time you Sustain the spell, you can repeat the attack against any creature within 120 feet.\n\nHeightened (+2) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"WPu3UE3kTXSLqO40","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.spiritual-weapon","name":"Spiritual Weapon","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["attack","concentrate","force","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"2d8","damageType":"force","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"A weapon made of pure magical force materializes and attacks foes you designate within range. This weapon has a ghostly appearance and manifests as a club, a dagger, or your deity's favored weapon.\n\nWhen you cast the spell, the weapon appears next to a foe you choose within range and makes a Strike against it. Each time you Sustain the Spell, you can move the weapon to a new target within range (if needed) and Strike with it. The spiritual weapon uses and contributes to your multiple attack penalty.\n\nThe weapon's Strikes are melee spell attacks. Regardless of its appearance, the weapon deals 2d8 force damage. You can deal damage of the type normally dealt by the weapon instead of force damage (or any of the available damage types for a versatile weapon). No other statistics or traits of the weapon apply, and even a ranged weapon attacks adjacent creatures only. Despite making a spell attack, the spiritual weapon is a weapon for purposes of triggers, resistances, and so forth.\n\nThe weapon doesn't take up space, grant flanking, or have any other attributes a creature would. The weapon can't make any attack other than its Strike, and feats or spells that affect weapons do not apply to it.\n\nHeightened (+2) The weapon's damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"Fq9yCbqI2RDt6Orw","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.splinter-volley","name":"Splinter Volley","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["attack","concentrate","manipulate","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"VARIABLE","text":"2 or 3"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 or 2 creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"QrOXDstbGji5fsbX","formula":"4d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"QrOXDstbGji5fsbX":"4d6"}},"counteraction":false,"ritual":null,"description":"You launch a volley of splinters at your foes. Make a spell attack roll against a single creature. On a hit, the splinters deal 4d6 piercing damage. The splinters deal double damage on a critical hit and (floor(@item.level/2))[bleed] damage. You can spend a third action while casting this spell to fire splinters at two different targets instead of one. These attacks each increase your multiple attack penalty, but you don't increase your multiple attack penalty until after you make both spell attack rolls for splinter volley.\nHeightened (+2) Increase the damage dealt to each target by 4d6 and the persistent bleed damage by 1.","source":{"provider":"PAIZO","sourceId":"Bc6QqTmFV4q7G7L0","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.spys-mark","name":"Spy's Mark","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","scrying"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"target":"a wall or other solid, immobile surface","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"By pressing your hand to a wall or other solid immobile surface, you cause the crossed-swords symbol of the Firebrands—or a different symbol of your choosing—to appear on the targeted surface. This symbol is immobile. You can use an action, which has the concentrate trait, to shut your eyes and focus on the symbol, projecting your senses into the symbol. While projecting your senses, you can see, hear, and smell through the symbol using whatever senses you have (including natural senses like scent and darkvision and magical senses like see invisibility). You must be within 100 feet to sense through the symbol in this way. You can Dismiss the projection effect but can otherwise freely project your senses into the symbol at any time during the spell's duration.\n\nA creature can erase the symbol (and end the spell) by spending 3 Interact actions to scrub the symbol away. These actions do not need to be consecutive.\n\nHeightened (4th) The duration increases to 8 hours. You can sense through the symbol at a distance up to 500 feet away. Scrubbing the symbol requires 6 Interact actions.\n\nHeightened (9th) The symbol remains until the next time you make your daily preparations. You can sense through the symbol at a distance up to 1 mile away. Scrubbing the symbol requires 1 total minute of work.","source":{"provider":"PAIZO","sourceId":"LFcGNGLMkGlsnEKQ","book":"Pathfinder Lost Omens Firebrands","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.status","name":"Status","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","detection","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing living creature","area":null},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"As long as you and the target are on the same plane of existence and both alive, you remain aware of its present state. You know the target's direction from you, distance from you, and any conditions affecting it.\n\nHeightened (4th) The spell's range increases to 30 feet, and you can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"HTou8cG05yuSkesj","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.steel-fortifications","name":"Steel Fortifications","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","metal"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure several metal structures that consist of angled beams attached to one another at a central point, which can help block attacks. You creature up to three Large structures within range in unoccupied squares; each fortification is 8 feet long, 8 feet wide, and 8 feet tall. There must be enough room for a fortification in order to conjure it. A single fortification has an AC of 10 and is immune to critical hits and precision damage. It has Hardness 9, 60 Hit Points, and a BT of 30. Once a fortification is broken, it crumbles into sharp metal bits. Any creature adjacent to or sharing a space with a fortification when it is broken must attempt a Reflex save or take 2d6 persistent bleed damage.\n\nCreatures can pass through the spaces of a fortification, though Medium and larger creatures treat these spaces as difficult terrain. A Small or smaller creature can occupy the same spaces as a fortification; doing so grants them standard cover. Similarly, a Medium creature can occupy the same spaces as a fortification, gaining standard cover in the process. A Medium or smaller creature can climb a fortification with a successful athletics check.","source":{"provider":"PAIZO","sourceId":"wQDrc0LDWaBA5Xa8","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sticky-fire","name":"Sticky Fire","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["attack","concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"Y4V4JBiCLTGoazyp","formula":"1d8","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false},{"id":"iCnezETP96bUMaKq","formula":"1d8","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"Y4V4JBiCLTGoazyp":"1d8","iCnezETP96bUMaKq":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You send a bubble of viscous liquid that sparks into flame. Make a spell attack roll against the target's AC, dealing 1d8 fire damage and 1d8 persistent fire damage on a hit. The target is Enfeebled 1 until they recover from their persistent fire damage.\nHeightened (+2) The initial and persistent fire damage increase by 1d8.","source":{"provider":"PAIZO","sourceId":"Vseo7VIy8mzINUES","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.stupefy","name":"Stupefy","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"varies","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You dull the target's mind, depending on its Will save.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Stupefied 1 until the start of your next turn.\n\nFailure The target is Stupefied 2 for 1 minute.\n\nCritical Failure The target is Stupefied 3 for 1 minute.","source":{"provider":"PAIZO","sourceId":"CQb8HtQ1BPeZmu9h","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sudden-blight","name":"Sudden Blight","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","void"],"traditions":["DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":true},"damage":[{"id":"0","formula":"2d10","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d10"},"areaFeet":0},"counteraction":true,"ritual":null,"description":"You accelerate the processes of decay in the area. Each living creature in the area takes 2d10 void damage with a basic Fortitude save. A creature afflicted by a disease takes a –2 circumstance penalty to this save. You can also direct the blight to rot all Small and Tiny non-creature plants in the area, eliminating non-magical undergrowth and any resulting difficult terrain, cover, and concealment. Sudden blight attempts to counteract any magical effect on the plants before withering them.\nHeightened (+1) The damage increases by 1d10.","source":{"provider":"PAIZO","sourceId":"XFtO4BBI22Uox2QP","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.sudden-bolt","name":"Sudden Bolt","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","electricity","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature or object","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"4d12","damageType":"electricity","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d12"}},"counteraction":false,"ritual":null,"description":"You call down a small bolt of lightning on the target, dealing 4d12 electricity damage.\n\nHeightened (+1) The damage increases by 1d12.","source":{"provider":"PAIZO","sourceId":"zK0e9d9DSnxC4eAD","book":"Pathfinder #151: The Show Must Go On","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.summon-elemental","name":"Summon Elemental","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","summon"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You summon a creature that has the elemental trait and whose level is 1 or lower to fight for you.\n\nHeightened As listed in the summon trait.","source":{"provider":"PAIZO","sourceId":"lpT6LotUaQPfinjj","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summoners-precaution","name":"Summoner's Precaution","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","contingency","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"10 minutes"},"requirements":"You have an eidolon."},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until your next daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a buffer in the link between yourself and your eidolon in order to prevent you from falling alongside your bonded ally. You gain the reaction; after using it, the spell ends.","source":{"provider":"PAIZO","sourceId":"cwXiKPkZrIupjwlQ","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.summoners-visage","name":"Summoner's Visage","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","polymorph"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"your eidolon","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transform your eidolon into your identical twin. Assuming you are a humanoid, the eidolon gains the humanoid trait in addition to its other traits while it's in this form, as well as any other trait related to your form (such as elf or gnome). Your eidolon gains a +4 status bonus to Deception checks to Impersonate you and can add its level to such checks even if it's untrained.\n\nAlthough your eidolon looks like you, it doesn't gain any new abilities, and its statistics don't change in any way-the transformation is purely cosmetic. If this transformation reduces your eidolon's size, the eidolon loses any other effects of its larger size, such as any increase to reach. Your eidolon can still use gear only if it has the eidolon trait, which allows eidolons to use it. Any such eidolon items the eidolon was wearing change size and shape, if necessary, and its effects remain active.\n\nYou can Dismiss the spell.\n\nHeightened (4th) The duration increases to 1 hour.","source":{"provider":"PAIZO","sourceId":"vb2dFNtbofJ7A9BW","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.sun-blade","name":"Sun Blade","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["attack","concentrate","fire","focus","light","manipulate","vitality"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"1d4","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4"}},"counteraction":false,"ritual":null,"description":"You fire a ray of burning sunlight from your weapon. You must be wielding a sword or spear to cast sun blade, and you perform this spell's somatic component with the weapon. Make a spell attack roll. The ray deals 1d4 fire damage. If the target is unholy, the ray deals an additional 1d4 spirit damage, and if the target is undead, the ray deals an additional 1d4 vitality damage (both effects apply against creatures that are both unholy and undead). If you are in an area of bright natural sunlight, increase the die size of each damage die by one step (from d4 to d6).\n\nCritical Success The ray deals double damage.\n\nSuccess The ray deals full damage.\n\nHeightened (+1) The damage increases by 1d4 fire, 1d4 spirit, and 1d4 vitality (or 1d6 of each type of damage in bright natural sunlight).","source":{"provider":"PAIZO","sourceId":"pMTltbI3S3UIuFaR","book":"Pathfinder Lost Omens Character Guide","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.sure-footing","name":"Sure Footing","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","healing","manipulate"],"traditions":["DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"You free the target's limbs from ailments that impede mobility. Attempt to counteract an effect of your choice imposing one of these conditions on the target: , , or . If you didn't counteract the effect, but you would have if its counteract rank were 2 lower, instead suppress the effect until the beginning of your next turn. The effect's duration doesn't elapse while it's suppressed.\n\nThis spell can't counteract or suppress curses, diseases, or conditions that are part of the target's normal state.\nHeightened (4th) Add , , and to the list of conditions.\n\nHeightened (6th) As 4th rank, plus add\n\nHeightened (8th) As 4th rank, plus add petrified and .","source":{"provider":"PAIZO","sourceId":"BCuHKrDeJ4eq53M6","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.swallow-light","name":"Swallow Light","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["cold","concentrate","darkness","manipulate","void"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 magical light effect","area":{"shape":"CONE","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"ab3ptdpkosjwwhas","formula":"1d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false},{"id":"ykcgd1y626dthnzt","formula":"1d6","damageType":"void","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"ab3ptdpkosjwwhas":"1d6","ykcgd1y626dthnzt":"1d6"}},"counteraction":true,"ritual":null,"description":"You draw magical light into your open mouth, consuming it and turning its essence into fuel for a gout of life-draining shadows. Attempt a counteract check against the light effect. If you successfully counteract it, you gain a breath weapon of chilling shadows you can use until the spell ends. Exhaling the breath is a two-action activity. The breath weapon is a 15-foot cone and deals 1d6 cold damage plus 1d6 void damage. Creatures in the area can attempt a basic Reflex save against your spell DC. Once activated, you can't use the breath weapon again for [[/r 1d4 #Rounds]] rounds.\n\nHeightened (+2) Increase the damage of the breath weapon by 1d6 cold damage and 1d6 void damage.","source":{"provider":"PAIZO","sourceId":"4Sg6ZngswhphxiBD","book":"Pathfinder #181: Zombie Feast","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.sweetest-solstice","name":"Sweetest Solstice","kind":"RITUAL","rank":2,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"sesame paste, sugar, rice balls, food dye, cooking pots, and utensils with a total value of 2 gp × the spell rank × the settlement's level"},"targeting":{"range":{"kind":"NONE"},"target":"a settlement with a level equal to or lower than twice the ritual's level","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Cooking Lore (expert)","secondaryChecks":"Diplomacy, Performance, or Religion","secondaryCasters":3},"description":"On long winter nights, many families in Tian Xia share a dish of glutinous rice balls. Wealthier families also dye these rice balls an auspicious pinkish-red in jujube juice and might serve or stuff them with expensive sweetened pastes of red beans, sesame, taro, or lotus. Sweetest solstice is a folk ritual that incorporates this tradition and allows entire villages to experience communal goodwill by celebrating a luxurious version of this dish together.\n\nThis ritual is performed over 1 hour of cooking a soup of crushed black sesame and sugar in several large cauldrons while good-natured jokes and puns praising Daikitsu, Kofusachi, and other benevolent deities are uttered; quips inspired by Hei Feng and Sun Wukong are usually included in these jovialities, for these rambunctious deities are always ready for feasts and humor. Each time a joke or pun is made, a rice ball is dropped into the boiling soups.\n\nThis ritual can only be performed once each winter season. If performed on the night of the winter solstice, the DCs of the ritual's skill checks are reduced by 2.\n\nIf the ritual is successful, the delicious black sesame soup, like the longest of nights, seems never-ending and even hides windfalls of chewy sweetness. Sometimes, this small mercy of hot meals, and the hope for pleasant surprises to come, is all a community needs to endure the bleakest of winters together.\n\nCritical Success The pot contains enough black sesame soup and rice balls to feed a hot meal to everyone in the settlement for a month. The casters of the ritual gain a +1 status bonus to saves against emotion and fear effects until the end of winter.\n\nSuccess The pot contains enough black sesame soup and rice balls to feed a hot meal to everyone in the settlement for a week. The casters of the ritual gain a +1 status bonus to saves against fear effects for 1 month or until the end of winter, whichever comes first.\n\nFailure The ritual has no effect.\n\nCritical Failure The soup becomes tainted; it not only provides no nourishment but spreads food poisoning through the town (this might have disastrous effects). The casters of the ritual become particularly affected by illness and become Sickened 4 and can't reduce the condition for 12 hours.","source":{"provider":"PAIZO","sourceId":"wAJ8mXPYbyAg0qWX","book":"Pathfinder Season of Ghosts Hardcover Compilation","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.teeth-to-terror","name":"Teeth to Terror","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","fear","illusion","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature with teeth","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"lhtty9ufzih9gfue","formula":"2d4","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false},{"id":"pxacolqtc1zeoqw3","formula":"1d4","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"The target believes its teeth are falling out, crawling along its face, stabbing into its body, and cramming themselves down its throat. The target takes 2d4 mental damage and 1d4[persistent,mental], depending on its Will save. The target takes a -1 circumstance penalty to Strikes with its jaws or teeth while it is taking persistent mental damage.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage and no persistent mental damage.\n\nFailure The target takes full damage and persistent mental damage and is Frightened 1.\n\nCritical Failure The target takes full damage and persistent mental damage and is Frightened 3.\n\nHeightened (+2) You can target two additional creatures, the mental damage increases by 2d4, and the persistent mental damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"avT46uIH3xYJPSv4","book":"Pathfinder #181: Zombie Feast","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.telekinetic-maneuver","name":"Telekinetic Maneuver","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["attack","concentrate","force","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a rush of telekinetic power, you move a foe or something they carry. You can attempt to , , , or the target using a spell attack roll instead of an Athletics check.","source":{"provider":"PAIZO","sourceId":"mrDi3v933gsmnw25","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.the-parrots-whisper","name":"The Parrot's Whisper","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["auditory","concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call forth an echo of the gossiping parrot from the tale of the Witch and the Weaver to whisper the secrets of a creature you can see within range. The garrulous parrot is known to chatter on for some time while deciphering the information you seek. The target must attempt a Will saving throw.\nCritical Success The parrot chatters about various random topics for 1 round and reveals no relevant information.\n\nSuccess The parrot tells you the target's highest weakness at the start of your next turn. In the meantime, the parrot chatters about various random topics.\n\nFailure The parrot tells you the target's highest weakness immediately, but sticks around for 1 round to chatter.\n\nCritical Failure The parrot tells you the target's highest weakness immediately, and you can ask the parrot one question about the target creature. You might need to collaborate with the GM to narrow down the question. At the start of your next turn, the parrot answers the question truthfully.","source":{"provider":"PAIZO","sourceId":"8NK5HtDxM3Qktu8H","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.the-queens-rainbow","name":"The Queen's Rainbow","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["auditory","concentrate","linguistic","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"LINE","feet":60}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You tell the story of the Queen of Bees and her retinue trying to pass through a rainbow on their way to visit the King of Spiders. You conjure forth a large, transparent rainbow. Creatures who enter or begin their turn in the rainbow's space must succeed at a Fortitude saving throw or become for 1 round (or for 1 round on a critical failure).","source":{"provider":"PAIZO","sourceId":"V05lB4VsSMiMMsZJ","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.thermal-remedy","name":"Thermal Remedy","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","fire","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"TOUCH"},"target":"up to 1 gallon of non-magical liquid or up to 5 pounds of food","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You adjust the delicate levels of bitter ingredients in food and drink to draw out their full restorative and fortifying properties. Choose one of the benefits listed below. Any creature that consumes the targeted drink or food gains that benefit. Up to 10 creatures can partake in the meal, and a creature gets no extra benefit for consuming more than one portion.\n\n- Gain 5 temporary Hit Points.\n\n- Gain resistance 2 to fire.\n\n- Gain a +1 circumstance bonus to saves against disease.\n\nHeightened (4th) Your remedy provides two benefits of your choice instead of one. The temporary Hit Points increase to 10, the resistance to fire increases to 3, the bonus against disease increases to +2, and the duration is 2 hours.\n\nHeightened (7th) The remedy provides all three benefits. The temporary Hit Points increase to 15, the resistance to fire increases to 5, the bonus against disease increases to +3, and the duration is 8 hours.","source":{"provider":"PAIZO","sourceId":"l194BTf9cAFlSQ96","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.thundering-dominance","name":"Thundering Dominance","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"your companion or eidolon","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shroud the target in a powerful predatory aura and amplify its vocalizations. It gains a +1 status bonus to Intimidation checks. Once during this spell's duration, it can take the action.\n\nHeightened (+2) The status bonus to Intimidation checks increases by 1 (to a maximum of a +4 status bonus for an 8th-rank spell), and the damage from the roar increases by 2d8.","source":{"provider":"PAIZO","sourceId":"mMgLHTLHjjGa206q","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.timely-tutor","name":"Timely Tutor","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["manipulate","mental"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"TOUCH"},"target":"your eidolon or familiar","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You serve as an astral connection between your eidolon or familiar and the Akashic Record-a demiplane consisting of a comprehensive psychic library-then turn to the creature for advice. If you cast this spell on your familiar, your familiar adds your spellcasting ability modifier on checks to Recall Knowledge with the Lore skill of your choice, much like it does for Acrobatics and Stealth. Your familiar must have the speech familiar ability in order to share any information it learns with you. If you cast this spell on your eidolon, it instead becomes trained in the Lore skill.\n\nIf you lose physical contact with the target, its connection to the Akashic Record is severed and timely tutor immediately ends.","source":{"provider":"PAIZO","sourceId":"OhgfPzB5gymZ0IZM","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.translate","name":"Translate","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"The target can understand the meaning of a single language it is hearing or reading when you cast the spell. This doesn't let it understand codes, language couched in metaphor, and the like (subject to GM discretion). If the target can hear multiple languages and knows that, it can choose which language to understand; otherwise, choose one of the languages randomly.\n\nHeightened (3rd) The target can also speak the language.\n\nHeightened (4th) You can target up to 10 creatures, and targets can also speak the language.","source":{"provider":"PAIZO","sourceId":"vTQvfYu2llKQedmY","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.tremorsense","name":"Tremorsense","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You become aware of vibrations in the ground around you. You gain tremorsense as an imprecise sense with a range of 30 feet. As normal for tremorsense, you can detect a creature only if it's on the same surface as you and only if the subject is moving along (or burrowing through) the surface.\n\nHeightened (3rd) The spell's duration is 1 hour.\n\nHeightened (5th) The spell's duration is 8 hours.","source":{"provider":"PAIZO","sourceId":"EAYViUegegttJF1u","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.triple-time","name":"Triple Time","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["bard","cantrip","composition","emotion","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":60}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Your music sets a fast pace. You and all allies in the area gain a +10-foot status bonus to all Speeds for 1 round.","source":{"provider":"PAIZO","sourceId":"c8R2fpk88fBwJ1ie","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.umbral-extraction","name":"Umbral Extraction","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","illusion","manipulate","mental","shadow"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You prepare to steal spells from your foes, ripping them from the foe's shadow to stow them in an ephemeral pocket in the Shadow Plane. You gain a temporary spell slot, which you can fill only by stealing a spell from an enemy spellcaster. During umbral extraction's duration, you can use the Steal action to attempt to take one of the foe's prepared spells or unused spontaneous spell slots instead of an item. You can also make one attempt to Steal as part of Casting umbral extraction. If you succeed at your check to Steal a spell, you deal 1d4 mental damage to the target per rank of the spell stolen due to the psychological toll of the spiritual emptiness created by wrenching the spell away, and you place the stolen spell in your temporary spell slot. It gains the shadow trait if cast from this temporary slot.\n\nDetermine the stolen spell at random from the target's spells that are 1 rank lower than umbral extraction, or from spells of the same rank if you got a critical success. If the target has no spell slots of that rank, use the highest rank below that in which the target does have a spell slot. (If the target has no eligible spells, you get nothing, but you can continue to attempt to Steal spells for the remaining duration.) If the target is a prepared caster, you randomly steal one of their prepared spells. If the target is a spontaneous caster, you instead steal an unexpended spell slot of the appropriate rank and determine the spell at random from all the target's known spells at that level. You can't steal a target's innate spells, focus spells, or cantrips. You know what the spell is as soon as you steal it, and your temporary spell slot becomes a spell slot of the same rank as the spell you stole.\n\nAs normal, you can Steal only from a target within your reach. Once you've placed a spell in your temporary spell slot, you can't attempt to Steal more spells. If you succeed at your Thievery check, you must take the spell you stole. Even if you're a spontaneous caster, you can use the temporary spell slot only to cast the stolen spell and you can cast only the stolen spell from your temporary spell slot. When umbral extraction ends, you lose the temporary spell slot and any spell still stored in it. When you cast umbral extraction, any previous casting of umbral extraction currently affecting you ends.","source":{"provider":"PAIZO","sourceId":"EDwakYQTS1t6XHD4","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.umbral-mindtheft","name":"Umbral Mindtheft","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","illusion","manipulate","mental","shadow"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"3fs8oc0vhfp42yxz","formula":"2d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You prepare to steal a broad field of knowledge from another creature, siphoning it from their mind and storing it in a pocket of the Shadow Plane connected to your own mind. During the spell's duration, you can use the action to attempt to take one Lore skill proficiency from a creature instead of Stealing an item. You can also make one attempt to Steal as part of Casting the Spell. If you succeed at your check to Steal a Lore skill, you deal 2d6 mental damage to the target if they were trained in that skill, plus 2d6[mental] damage per proficiency rank they have in that skill above trained, as the sudden loss of knowledge leaves an aching absence in the target's mind. Determine the Lore skill at random from among those known by the target; on a critical success, you learn what Lore skills the creature is proficient in and can select the skill rather than choosing at random. If the target isn't trained in any Lore skills, you get nothing, but you can continue to attempt to Steal Lore from other creatures for the remaining duration. The target loses the benefits of its training in that Lore skill, and you gain their proficiency rank in that Lore skill. This effect lasts until your next daily preparations or until you are incapacitated, in which case the Lore siphons back into the target creature's mind from the Shadow Plane, wherever you both may be. As normal, you can Steal only from a target within your reach. Once you've stolen one Lore skill, you can't attempt to Steal more Lore. If you succeed at your Thievery check, you must take the Lore you stole.","source":{"provider":"PAIZO","sourceId":"uopaLE01meX11Mbw","book":"Pathfinder #181: Zombie Feast","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.valiant-anthem","name":"Valiant Anthem","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["auditory","concentrate","emotion","focus","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You chant a rallying cry to bolster your allies. Your allies in the area gain a +10-foot status bonus to all Speeds and a +1 status bonus to attack rolls.","source":{"provider":"PAIZO","sourceId":"nRsBM1zkhMmV3VST","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.veil-of-spirits","name":"Veil of Spirits","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate","spirit"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You draw on the essence of spiritual energy surrounding you to manifest a misty veil. When a creature that isn't immune to spirit damage begins its turn within the area, it must attempt a Reflex save. You can Dismiss the veil.\nCritical Success The creature is unaffected.\n\nSuccess The creature is until the beginning of its next turn.\n\nFailure The creature is dazzled and gains a weakness to spirit damage equal to half your level until the beginning of its next turn as spiritual energy clings to it. A creature with spiritsense can't use that imprecise sense while it's dazzled in this way.\n\nCritical Failure As failure, but the weakness is equal to your level.","source":{"provider":"PAIZO","sourceId":"lQbfgAu9uVJQC7x4","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vicious-jealousy","name":"Vicious Jealousy","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"The target is overcome by deep jealousy and resentment that twists its mind against other creatures. It must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess For 1 round, the target no longer treats anyone as its allies. The spell then ends.\n\nFailure The target no longer treats anyone as its allies. The target can't take the reaction or any action that would directly benefit another creature, such as casting a beneficial spell on them, though it can still take actions that indirectly benefit other creatures, such as fighting the same foes.\n\nCritical Failure As failure, and whenever the target starts its turn within reach of a creature it previously considered an ally, it must spend its first action on its turn to berate the creature or otherwise wave it away.\n\nHeightened (4th) You can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"h6VoHgPC0JCTVzgP","book":"Pathfinder #181: Zombie Feast","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vision-of-weakness","name":"Vision of Weakness","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["cursebound","focus","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You focus your gaze on a creature and gain a flash of divine insight into its nature. If the creature has any weaknesses, you learn them, as well as which of its three saving throw modifiers is lowest.\n\nYou also learn an inherent understanding of its movements and gain a +2 status bonus to your next attack roll (or skill check made as part of an attack action) against that foe before the end of your turn.\n\nThe target is then temporarily immune to Vision of Weakness for 1 day.","source":{"provider":"PAIZO","sourceId":"NhNKzq1DvFxkvTEc","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.voice-on-the-breeze","name":"Voice on the Breeze","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["air","concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"10 miles"},"area":{"shape":"BURST","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You whisper a secret message or sound into the wind, which carries it to a designated spot. The message travels to a specific within range that's familiar to you, provided there's a path for the wind to follow between you and the area. The gentle breeze goes all but unnoticed until it reaches its destination, where it delivers its whisper-quiet message. The message is delivered regardless of who or what is present to hear it, even if no one receives it at all. Once the message is delivered, the spell ends.\n\nYour message can contain no more than 25 words, 1 round's worth of other sounds, or a simple rustling in the air at the target location. It moves at a speed of your choosing between 1 mile per hour and 1 mile per 10 minutes; when it arrives, the wind swirls around the area and whispers the full message. A voice on the breeze can't activate magical effects triggered by voices.\n\nHeightened (4th) The range increases to 1,000 miles, and the message can contain up to 100 words.","source":{"provider":"PAIZO","sourceId":"d18m4AAaxJQqUEh2","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.vomit-swarm","name":"Vomit Swarm","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"2d8","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You belch forth a swarm of magical vermin. You evoke and shape the creatures from your own imagination, allowing you to change the appearance of the creatures (typically a mix of centipedes, roaches, wasps, and worms), but this doesn't change the effect of the spell. The vermin swarm over anyone in the area, their bites and stings dealing 2d8 piercing damage (basic Reflex save). A creature that fails its saving throw also becomes Sickened 1. Once the spell ends, the swarm disappears.\nHeightened (+1) The damage increases by 1d8.","source":{"provider":"PAIZO","sourceId":"cB17yFc9456Pyfec","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.warping-pull","name":"Warping Pull","kind":"SPELL","rank":2,"rarity":"UNCOMMON","traits":["concentrate","manipulate","teleportation"],"traditions":["ARCANE"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 willing creature that would take damage from the triggering effect","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger An effect would deal damage to an ally within range.\nYou get an ally out of danger with a teleporting pull. You teleport the target to an unoccupied square up to 10 feet closer to you. The target gains resistance 5 to all damage against the triggering effect.\nHeightened (+2) The resistance increases by 5.","source":{"provider":"PAIZO","sourceId":"UtINSoEJ0u630ia4","book":"Pathfinder Lost Omens Shining Kingdoms","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.warriors-regret","name":"Warrior's Regret","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","curse","emotion","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"1d8","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"Regret eats away at the target's mind, punishing it for its violence until it ceases its hostility. The target must attempt a Will save.\n\nCritical Success The target is unaffected.\n\nSuccess At the end of its next turn, the target takes 1d8 damage per different creature it intentionally damaged on that turn (1d8 if it damaged one creature, 2d8 if it damaged two different creatures, and so on). The maximum is 4d8 if it damaged 4 different creatures.\n\nFailure As success, except the curse damages the target at the end of each of its turns and lasts until the target spends a complete round without intentionally damaging another creature.\n\nCritical Failure As success, except the curse damages the target at the end of each of its turns and lasts until the target spends 24 hours atoning for its perceived sins.\n\nHeightened (+2) The amount of mental damage the target takes for each creature it damaged that turn increases by 1d8, and the maximum damage the target can take per turn increases by 4d8.","source":{"provider":"PAIZO","sourceId":"kIwA7kwp5E0AC3yM","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.water-breathing","name":"Water Breathing","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"up to 5 creatures","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The targets can breathe underwater.\n\nHeightened (3rd) The duration increases to 8 hours.\n\nHeightened (4th) The duration increases to until your next daily preparations.","source":{"provider":"PAIZO","sourceId":"MZGkMsPBztFN0pUO","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.water-walk","name":"Water Walk","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature","area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"The target can walk on the surface of water and other liquids without falling through. It can go underwater if it wishes, but in that case it must Swim normally. This spell doesn't grant the ability to breathe underwater.\n\nHeightened (4th) The spell's range increases to 30 feet, the duration increases to 1 hour, and you can target up to 10 creatures.","source":{"provider":"PAIZO","sourceId":"Seaah9amXg70RKw2","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.waterproof","name":"Waterproof","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 object up to 10 Bulk","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You prevent the target item from taking on water or becoming wet for the duration of the spell. The hydrophobic properties of the spell also grant resistance 10 to acid and a +2 bonus to saves and DCs against damaging effects with the water or acid traits.\n\nHeightened (4th) The duration is 1 day.\n\nHeightened (8th) The duration is unlimited.","source":{"provider":"PAIZO","sourceId":"RS1nrqEjEi1ZlC53","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.web","name":"Web","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":{"shape":"BURST","feet":10}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You create a sticky web in the area that impedes creatures' movement. Squares filled with the web are difficult terrain. Each time a creature in the web begins to use a move action or enters the web during a move action it's using, it must attempt an athletics check or Reflex save against your spell DC to avoid taking a circumstance penalty to its Speeds or becoming . A creature that gets out of the web ceases to take a circumstance penalty to its Speed from the web. Each square can be cleared of the web by a single attack or effect that deals at least 5 slashing damage or 1 fire damage. A square has AC 5, and it automatically fails its saving throws.\nCritical Success The creature is unaffected, and it doesn't need to attempt further Athletics checks or saving throws against the web this turn. If it used an Athletics check, it clears the web from every square it leaves during its movement.\n\nSuccess The creature is unaffected during its action. If it used an Athletics check, it clears the web from every square it leaves during its movement.\n\nFailure The creature takes a –10-foot circumstance penalty to its Speeds until the start of its next turn.\n\nCritical Failure The creature is immobilized until the start of its next turn, after which it takes a –10-foot circumstance penalty to its Speeds for 1 round. It can attempt to to remove its immobilized condition.\nHeightened (4th) The spell's area increases to a , and its range increases to 60 feet.","source":{"provider":"PAIZO","sourceId":"9s5tqqXNzcoKamWx","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.with-friends-like-these","name":"With Friends like These","kind":"SPELL","rank":2,"rarity":"COMMON","traits":["concentrate","emotion","manipulate","mental"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"30"},"target":"2 creatures","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a subtle dissonance between creatures, driving them apart. Each target must attempt a Will save.\nCritical Success The creature is unaffected.\n\nSuccess The creature becomes Sickened 1.\n\nFailure The creature becomes Sickened 2. While sickened this way, it doesn't treat any other target of the spell as an ally.\n\nCritical Failure As failure, and it can't end a move action within 10 feet of any other target as long as it is sickened.\nHeightened (+2) You can target one additional creature.","source":{"provider":"PAIZO","sourceId":"GF7mOra8KPTW5Ggb","book":"Pathfinder Lost Omens High Seas","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.worms-repast","name":"Worm's Repast","kind":"SPELL","rank":2,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 corporeal creature","area":null},"duration":{"text":"see description","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"4d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Gnawing worms materialize within the flesh of the target creature, dealing 4d6 piercing damage and floor(@item.level/2)d6[persistent,piercing] damage. If the target is a non-skeletal corporeal undead creature, you deal an extra floor((@item.level/2)+1)d6[persistent,piercing] damage. The target must attempt a Fortitude save.\nCritical Success The worms writhe away harmlessly and the target takes no damage.\n\nSuccess The target takes full initial damage but no persistent damage, and the spell ends immediately.\n\nFailure The target takes full initial and persistent damage and is due to the pain for as long as it takes persistent damage.\n\nCritical Failure As failure, but the target takes double the initial damage and is also Slowed 1 by the pain for as long as it takes persistent damage.\nHeightened (+2) The initial and persistent damage increase by 2d6 and 1d6, respectively","source":{"provider":"PAIZO","sourceId":"H4oF5szC7aogqtvw","book":"Pathfinder #163: Ruins of Gauntlight","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.aberrant-whispers","name":"Aberrant Whispers","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["auditory","concentrate","focus","mental","sorcerer"],"traditions":[],"casting":{"time":{"kind":"VARIABLE","text":"1 to 3"}},"targeting":{"range":{"kind":"NONE"},"target":"each foe in the area","area":{"shape":"EMANATION","feet":5,"text":"5-foot emanation or more"}},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":3,"damage":{},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You utter phrases in an unknown tongue, assaulting the minds of those nearby. Each target must attempt a Will save. Regardless of the result of its save, each target is then temporarily immune for 1 minute. For each additional action you use when Casting the Spell, increase the emanation's radius by 5 feet.\n\nSuccess The target is unaffected.\n\nFailure The target is Stupefied 2.\n\nCritical Failure The target is .\nHeightened (+3) The initial radius increases by 5 feet.","source":{"provider":"PAIZO","sourceId":"qhJfRnkCRrMI4G1O","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.access-lore","name":"Access Lore","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["focus","fortune","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You sift through the multiverse's divine knowledge, seeking out tidbits related to a particular subject. Choose one Lore skill. You temporarily gain the same proficiency rank in that Lore skill as your proficiency rank for your oracle spellcasting.","source":{"provider":"PAIZO","sourceId":"LbPLNWlLCxKCo5gF","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.agonizing-despair","name":"Agonizing Despair","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","emotion","fear","manipulate","mental"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"4d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"Your target's mind tumbles down a deep well of dread, dwelling so intently on deep-seated fears that it's painful. The target takes 4d6 mental damage with a Will saving throw.\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage and becomes Frightened 1.\n\nFailure The target takes full damage and becomes Frightened 2.\n\nCritical Failure The target takes double damage and becomes Frightened 3.\nHeightened (+1) Increase the damage by 2d6.","source":{"provider":"PAIZO","sourceId":"nplNt08TvokZUxtR","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.ancestral-defense","name":"Ancestral Defense","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["focus","fortune","manipulate","mental","oracle"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You are about to attempt a Will save.\nYour ancestor protects you against those who would bend your will. You roll the triggering save twice and use the better result.","source":{"provider":"PAIZO","sourceId":"J5KrjQKCg2PrF1vz","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.angelic-wings","name":"Angelic Wings","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","light","manipulate","sorcerer"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"3 rounds","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Wings of pure light spread out from your back, granting you a fly Speed equal to your Speed. Your wings cast bright light in a 30-foot radius. When this spell's duration would end, if you're still flying, you float to the ground, as .\n\nHeightened (5th) The duration increases to 1 minute.","source":{"provider":"PAIZO","sourceId":"kRsmUlSWhi6PJvZ7","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.animal-vision","name":"Animal Vision","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 animal","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You tap into the target's senses, allowing you to sense whatever it senses for the spell's duration. If the target wishes to prevent you from doing so, it can attempt a Will save, negating the spell on a success, but most animals don't bother to do so. While tapping into the target's senses, you can't use your own body's senses, but you can change back and forth from your body's senses to the target's senses using a Sustain action.","source":{"provider":"PAIZO","sourceId":"1HfusQ8NDWutGvMx","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.annunciation-of-the-outer-gate","name":"Annunciation of the Outer Gate","kind":"SPELL","rank":3,"rarity":"RARE","traits":["auditory","concentrate","mental"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":30}},"duration":{"text":"10 minutes (see text)","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You announce yourself in the name of certain grim pacts that predate mortal life. This is not a compulsion, but rather an invitation of sorts. The invitation is understood by creatures in the area with telepathy and any who understand Aklo, Chthonian, Empyrean, Fey, or Utopian.\n\nThose who accept the invitation cannot take hostile action against others who agreed until 10 minutes pass and can communicate telepathically with them during that time. This effect ends immediately if any hostile action is taken against a creature that agreed.\n\nThose creatures who decline the choice or do not understand it must attempt a Will save.\nCritical Success Nothing happens.\n\nSuccess The creature is Frightened 1. If it understood the invitation, its frightened status doesn't decrease at the end of any turn in which it damaged a creature that agreed to the invitation.\n\nFailure As success, but the creature is Frightened 2.\n\nCritical Failure As success, but the creature is Frightened 3.","source":{"provider":"PAIZO","sourceId":"L1JnU3RepQiWxysc","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.anointed-ground","name":"Anointed Ground","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","consecration","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"LONG","text":"1 minute"},"cost":"oils worth 3 gp"},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"BURST","feet":30,"text":"30-foot burst centered on you"}},"duration":{"text":"until the next time you make your daily preparations","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You sanctify the area, sprinkling it with certain oils and warding it against your foes. Choose aberrations, celestials, dragons, fiends, monitors, or undead. All creatures in the area gain a +1 status bonus to AC, attack rolls, damage rolls, and saving throws against the chosen creatures.","source":{"provider":"PAIZO","sourceId":"y3jlOfgsQH1JjkJE","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.antlion-trap","name":"Antlion Trap","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"area":{"shape":"BURST","feet":15}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You transmute the ground into a conical pit trap of loose sand that becomes difficult terrain for the duration. A creature or unsecured object that enters the sand or starts its turn in the sand is moved toward the center, depending on the result of its Reflex save. This is forced movement. If there isn't enough space near the center of the pit, affected creatures and objects move as far as they can without being blocked, up to the amount set by their saving throw outcomes.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature moves 5 feet toward the center.\n\nFailure The creature moves 10 feet toward the center.\n\nCritical Failure As failure, and the creature becomes in the pit. It can attempt to against your spell DC.\n\nHeightened (+2) Increase the area of the spell and the amount a creature moves on a failure by 5 feet.","source":{"provider":"PAIZO","sourceId":"5JGSo1tgDEehqbWm","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.aqueous-orb","name":"Aqueous Orb","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":true,"ritual":null,"description":"A sphere of water 10 feet in diameter forms in an unoccupied space in range, either on the ground or on the surface of a liquid.\n\nWhen you Cast this Spell and each time you Sustain it, you can roll the orb, moving it up to 10 feet along the ground or the surface of a liquid.\n\nThe orb can move through the spaces of any creatures or obstacles that wouldn't stop the flow of water. It extinguishes non-magical fires it moves through of its size or smaller, and it attempts to counteract any magical fires it moves through. If it fails to counteract a given fire, it can't counteract that fire for the duration of the spell.\n\nThe orb can engulf Large or smaller creatures it moves through, and it can contain as many creatures as fit in its space. The orb can try to engulf the same creature only once per turn, even if you roll it onto a creature's space more than once. Any Large or smaller creature whose space the orb tries to move through can attempt a Reflex save.\n\nSuccess The creature can either let the orb pass (remaining in its space or moving out of the orb's path into a space of the creature's choice) or allow itself to be pushed in front of the orb to the end of the orb's movement.\n\nFailure The creature is engulfed in the orb. It moves along with the orb and must hold its breath or begin suffocating (unless it can breathe in water). An engulfed Medium or smaller creature and anyone trying to affect that creature follow the normal rules for aquatic battles. An engulfed Large creature is usually big enough that parts of it stick out from the water, and it can reach out of the water. The creature can get free either by Swimming with a successful athletics check or by Escaping against your spell DC. A freed creature exits the orb's space and can immediately breathe.\n\nCritical Failure As failure, but the creature can't Swim to get free.","source":{"provider":"PAIZO","sourceId":"oUDNCArkQTdhllxD","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.arcane-weaving","name":"Arcane Weaving","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 day"},"cost":"rare silks worth a total value of 20 gp x the spell rank"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (expert)","secondaryChecks":"Arcana, Crafting, or Occultism","secondaryCasters":1},"description":"You and the secondary casters weave together spells (and, if anadis, silk) in a complex ritual that combines magical learning with art, allowing all the participants to share spells they know with one another.\n\nSuccess You or any secondary caster can swap any spell in your spell repertoire for a spell in the spell repertoire of any other participant. This spell can't be a higher level than the ritual's level.\n\nFailure None of the participants can swap spells.\n\nCritical Failure As failure, and all participants are Stupefied 1 for 24 hours and can't reduce their stupefied condition below 1 for 24 hours.","source":{"provider":"PAIZO","sourceId":"dL3A7H4LlRH26Imo","book":"Pathfinder #169: Kindled Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.armor-of-bones","name":"Armor of Bones","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["focus","manipulate","oracle"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You ossify your physical form, mimicking the durability of bone. You gain resistance 3 to cold, electricity, fire, piercing, and slashing damage.\n\nHeightened (+1) Increase the resistance by 1.","source":{"provider":"PAIZO","sourceId":"pSNLufPPsReKQtJR","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.astral-rain","name":"Astral Rain","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["cantrip","concentrate","force","manipulate","psychic"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"CUBE","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"utw4ddumvvnvuqom","formula":"4d4","damageType":"untyped","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"utw4ddumvvnvuqom":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"You fling a mass of furious thoughts into the air, where they expand into numerous blades or other shapes that rain down. Any creature that's in the area or enters the area before the start of your next turn takes 4d4 bludgeoning or piercing damage (your choice), with a basic Reflex saving throw.\nHeightened (+1) The damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"nUSi2B7RhIKjaiXQ","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.awaken-portal","name":"Awaken Portal","kind":"RITUAL","rank":3,"rarity":"RARE","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"}},"targeting":{"range":{"kind":"DISTANCE","feet":10},"target":"1 portal","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (trained)","secondaryChecks":"Whichever is used for the primary check","secondaryCasters":0},"description":"You attempt to reactivate a dormant gate, portal, or by infusing it with magical energies. This ritual must be successfully performed twice, once at each location the portal connects. While the teleportation circles and portals found in the Abomination Vaults require no additional cost to awaken, other portals might require rare items or specific materials as a cost for this ritual at the GM's discretion—some portals might even be so powerful that this ritual cannot awaken them at all.\n\nCritical Success You awaken the portal. If its other side is awakened, the portal can be used normally and won't deactivate naturally. If its other side is not awakened, this side remains awakened for 1 year, possibly allowing you enough time to find and awaken the connecting portal.\n\nSuccess As critical success, but if the portal's other side is not awakened, this side remains awakened for only [[/r 1d6 #days]]{1d6 days} before it fades and falls dormant again.\n\nFailure You fail to activate the portal, and magical backlash leaves you Stupefied 1 for 24 hours.\n\nCritical Failure As failure, but in addition, a hostile creature is drawn through the portal and immediately attacks anyone present. The creature drawn through the portal varies, according to the portal's nature","source":{"provider":"PAIZO","sourceId":"AkF4yFcSCdhoULyZ","book":"Pathfinder #163: Ruins of Gauntlight","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.band-of-heroes","name":"Band of Heroes","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":["mythic"],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"all casters involved in ritual","area":null},"duration":{"text":"24 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Diplomacy (mythic) or Society (mythic)","secondaryChecks":"Diplomacy, Intimidation, or Society","secondaryCasters":2},"description":"The sun rises on a gathering of heroes bonded to a cause. While only one secondary caster can attempt the secondary check, each secondary caster must also spend 1 Mythic Point upon successful completion of the ritual (see below). A secondary caster who chooses not to spend the Mythic Point can't benefit from the ritual's effects.\nCritical Success As success, but the first time a caster gains the , , or condition during the ritual's duration, reduce the value of that condition by 1 (minimum 0).\n\nSuccess Each secondary caster must spend 1 Mythic Point. For the duration of the ritual, when a caster Aids another caster, they can attempt the associated check at mythic proficiency. On a success, the circumstance bonus the Aiding caster grants is increased to +2, and on a critical success, the circumstance bonus is increased to +5.\n\nFailure The ritual has no effect. The secondary casters don't need to each spend 1 Mythic Point.\n\nCritical Failure The ritual fails, and the casters rupture their own connections to their mythic destinies. None of the casters can gain Mythic Points for 1 week.","source":{"provider":"PAIZO","sourceId":"q9QGc0PJMFWxFOCz","book":"Pathfinder War of Immortals","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.battlefield-persistence","name":"Battlefield Persistence","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","oracle"],"traditions":[],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You are about to attempt a saving throw, but you haven't rolled yet.\nYou're difficult to deter in battle. You gain a +2 status bonus to the triggering save, and if the triggering save is against an incapacitation effect, it treats you as if you were 2 levels higher.","source":{"provider":"PAIZO","sourceId":"2jWVNdVlbJq84dfT","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.beastmaster-trance","name":"Beastmaster Trance","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","manipulate","mental"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TEXT","text":"1 mile"},"target":"one of your animal companions you can perceive","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You enter a magical trance that allows you to perceive through the senses of the target companion. You attempt Perception checks using your own Perception, but you have any special senses the target has, such as low-light vision or darkvision.\n\nThis spell grants no special method of communication with the chosen animal, so it follows any instructions you gave it before you entered the trance and, failing that, it does as it wishes.\n\nFor the duration of the trance, your own senses are muted, though you can still communicate. This lack of awareness makes you . You can't take actions with the attack or move traits.\n\nHeightened (6th) Increase the range to 100 miles and the duration to sustained up to 10 minutes. The target can hear you through the spell, allowing you to Command the Animal or use other actions that have the auditory trait.\n\nHeightened (8th) Increase the range to planetary and the duration to sustained up to 1 hour. You can communicate telepathically with the target for the duration of the trance.","source":{"provider":"PAIZO","sourceId":"5WM3WjshXgrkVCg6","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.behold-the-weave","name":"Behold the Weave","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate","prediction"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"MANUAL","text":"Aprimoramento com valores especificos por rank."},"counteraction":false,"ritual":null,"description":"You behold the many timelines that weave around a creature, and in so doing, you make one more likely to occur. The target must attempt a Will save.\nCritical Success You can make neither heads nor tails of the target's timeline, and the target is unaffected.\n\nSuccess The target must commit to a single action that it will take at some point during its next turn: \"Stride toward Valeros,\" \"Cast shield,\" \"Strike Amiri with your jaws.\" That action is now locked in, and the creature must attempt it, even if the situation has changed—if the creature stated that it would Strike at Amiri with its jaws, it must try to do so. If the creature is entirely unable to fulfill the action it committed to—for instance, if it had only 1 action left and Amiri was out of the range of its jaws Strike—it loses the last action of its turn as it reels in a temporal paradox. The creature can choose to lock in a 2- or 3-action activity if it prefers to do so, but if it does, it loses all the associated actions if it can't perform the activity on its turn. If the situation changes oddly (perhaps the creature is forcibly teleported away and has no idea which direction is \"toward Valeros\" any longer), the GM determines what happens.\n\nFailure As success, but the creature must commit at least two of its actions for the next turn—\"I will Stride toward Valeros and then Strike with my claws.\" All of these actions are similarly locked in and can't be changed, but the creature can take them in any order.\n\nCritical Failure As failure, but the creature must commit all of its actions for the next turn.\nHeightened (7th) Instead of affecting a single target, the spell affects all enemies within a 30-foot emanation.","source":{"provider":"PAIZO","sourceId":"3mQkAjexj6hhAnkR","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["HEIGHTENING_REQUIRES_MANUAL_RESOLUTION","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bind-undead","name":"Bind Undead","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 mindless undead creature with a level no greater than bind undead's spell rank","area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"With a word of power, you seize control of the target. It gains the minion trait. If you or an ally uses any hostile actions against the target, the spell ends.","source":{"provider":"PAIZO","sourceId":"GUeRTriJkMlMlVrk","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blastback","name":"Blastback","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["air","concentrate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":20}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"Zni2ysVqFC6plPs7","formula":"6d4","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"Zni2ysVqFC6plPs7":"1d4"},"areaFeet":0},"counteraction":false,"ritual":null,"description":"Trigger You fall more than 10 feet.\n\nYou hit the ground with a shuddering boom, propelling the force of your fall out in a wave. You take no damage from the fall as the displaced air allows you to land gently, but all other creatures in the spell's area take 6d4 bludgeoning damage. Creatures that fail their save are also pushed back 5 feet.\n\nHeightened (+2) The emanation increases by 10 feet, and the damage increases by 1d4.","source":{"provider":"PAIZO","sourceId":"YuCBhE9tGgN8G2zU","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.blazing-dive","name":"Blazing Dive","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["air","concentrate","fire","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"EMANATION","feet":10}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"3d4","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false},{"id":"1","formula":"3d6","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d4","1":"1d6"}},"counteraction":false,"ritual":null,"description":"Superheated air collects under you, buoying you high into the sky before you plummet back down in a fiery comet. You Fly 15 feet straight up into the air, then Fly in a straight line to an empty space of your choice on the ground within 60 feet. When you land, the blistering air blasts out from you, dealing 3d4 bludgeoning damage and 3d6 fire damage (basic Reflex save) to all creatures in a 10-foot emanation.\n\nHeightened (+1) The damage increases by 1d4 bludgeoning and 1d6 fire.","source":{"provider":"PAIZO","sourceId":"KEkPxx7Sm6Xf4W3s","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"PARTIAL","reasons":["MULTIPLE_DAMAGE_COMPONENTS"]}},{"id":"pf2e.spell.blinding-beauty","name":"Blinding Beauty","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["emotion","focus","incapacitation","manipulate","sorcerer","visual"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You channel the allure of your nymph bloodline into a terribly beautiful glance. Each enemy in the area must attempt a Will saving throw.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature is until the start of its next turn.\n\nFailure The creature is until the start of its next turn.\n\nCritical Failure The creature is Blinded for 1 minute.","source":{"provider":"PAIZO","sourceId":"Q56HLIHVKY6bC5W3","book":"Pathfinder Advanced Player's Guide","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blindness","name":"Blindness","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You blind the target. The effect is determined by the target's Fortitude save. The target then becomes temporarily immune for 1 minute.\n\nCritical Success The target is unaffected.\n\nSuccess The target is until its next turn begins.\n\nFailure The target is Blinded for 1 minute.\n\nCritical Failure The target is Blinded permanently.","source":{"provider":"PAIZO","sourceId":"VosLNn2M8S7JH67D","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blister-bomb","name":"Blister Bomb","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","disease","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":100},"area":{"shape":"BURST","feet":5}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You launch a small bomb enchanted with a fast-acting skin disease at your foes, causing their skin to break out in horrible bleeding sores. All creatures in the area of the burst must attempt a Fortitude save.\nCritical Success The creature is unaffected and is immune to blister pox for 1 week.\n\nSuccess The creature is Sickened 2.\n\nFailure The creature is afflicted with blister pox at stage 1.\n\nCritical Failure The creature is afflicted with blister pox at stage 2.\nBlister Pox (disease) Level 5; A creature can't reduce its sickened value below 1 while it's taking persistent bleed damage from blister pox\n\nStage 1 sickened 2 (1 round)\n\nStage 2 sickened 2 and 1d6 persistent bleed damage (1 round)\n\nStage 3 sickened 2 and 2d6 persistent bleed damage (1 round)\n\nStage 4 Sickened 3 and 2d6 persistent bleed damage (1 day)","source":{"provider":"PAIZO","sourceId":"3qx1axryNbl97ker","book":"Pathfinder Battlecry!","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.blood-in-the-water","name":"Blood in the Water","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","focus","hex","manipulate","spirit","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2},"requirements":"The target is taking persistent bleed damage or your last action dealt slashing damage to the target."},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature that can bleed","area":null},"duration":{"text":"1 minute","sustained":true},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"NCkXViQ3UkwGDWOr","formula":"2d6","damageType":"spirit","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":2,"damage":{"NCkXViQ3UkwGDWOr":"2d6"}},"counteraction":false,"ritual":null,"description":"Requirements The target is taking persistent bleed damage or your last action dealt slashing damage to the target.\n\nPredators are drawn to the scent of blood, and blood can disperse shockingly far in the water. You summon the spirits of aquatic predators to appear as a spectral swarm around the target. When you Cast or Sustain this Spell, the target takes 2d6 spirit damage (basic Reflex save). If the target takes any damage from the spell, it treats all water as difficult terrain for 1 round as the predators try to drag them down. The spectral predators don't take up space, grant flanking, or have any other attributes a creature would. If you deal slashing damage to the target while the spell is active, you automatically Sustain this Spell. If you cast blood in the water while a previous casting of this hex is still in effect, the previous effect ends.\n\nHeightened (+2) The damage dealt increases by 2d6.","source":{"provider":"PAIZO","sourceId":"CXpOlv2ZZq2jVbRX","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.bone-flense","name":"Bone Flense","kind":"SPELL","rank":3,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","DIVINE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 weapon that is either wielded by a member of the Red Mantis or is a praying mantis's leg Strike","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The target weapon becomes imbued with Achaekek's power and glows softly with crimson light akin to that shed by a candle. When a creature with a skeleton or exoskeleton takes damage from a Strike delivered by this weapon, the creature's bones nearest to the wound instantly sprout jagged, razor-sharp spurs that flense the muscle and flesh from inside out. The creature takes an additional 1d6 persistent bleed damage from the Strike. You can use the reaction.\n\nHeightened (+2) The persistent bleed damage increases by 1d6. The damage from Erupting Spurs increases by 4d6.","source":{"provider":"PAIZO","sourceId":"V4IpjSlefultlOuY","book":"Pathfinder Adventure: Prey for Death","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bonewall-bulwark","name":"Bonewall Bulwark","kind":"SPELL","rank":3,"rarity":"RARE","traits":["concentrate","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":5},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SPELL_ATTACK"},"damage":[{"id":"bVVua6iV5Q7ktuiB","formula":"3d10","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"bVVua6iV5Q7ktuiB":"1d10"}},"counteraction":false,"ritual":null,"description":"You create a miniature replica of the infamous Bonewall of Yled, a jumble of bones with threatening limbs reaching from it. The bulwark is 10 feet high, 10 feet long, and 1 foot thick. The bulwark has an AC of 10 and 30 Hit Points. You must create the bulwark in an unbroken open space so it doesn't pass through any creatures or objects, or the bulwark's dimensions are reduced to fit the smaller space. It must pass within 5 feet of you.\n\nThe bonewall bulwark grants cover from creatures on the opposite side. At the beginning of your turn, you may have the limbs attack a single creature you're aware of within 5 feet of the wall using your spell attack modifier and dealing 3d10 bludgeoning damage. This ignores cover and concealment provided by the bonewall bulwark.\n\nHeightened (+1) The bludgeoning damage increases by 1d10 and the HP of the wall increases by 10.","source":{"provider":"PAIZO","sourceId":"11pQoPJpSH2jp7h6","book":"Pathfinder Wake the Dead #4","license":"OGL","remaster":false},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.bottomless-stomach","name":"Bottomless Stomach","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","extradimensional","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 willing creature","area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create a shimmering extradimensional space accessible from the target's mouth. The space can hold objects and equipment, up to a total of 10 Bulk. This extradimensional storage doesn't hamper the target's ability to eat, drink, speak (if applicable), or otherwise act, as it only opens and closes when the target chooses.\n\nThe target can Interact to swallow an object of up to 1 Bulk, which doesn't harm the object or the target. If the extradimensional space is full, the target can't add any more objects until first removing one or more stored objects. Organic matter and living creatures can't be stored in this space. The extradimensional storage is obvious to any creature who looks into the target's mouth, as the entryway shimmers slightly, though this doesn't clearly reveal the contents inside.\n\nThe target can Interact to spit out a single object of its choice, causing the object to fall to the ground in the target's space. The target can Interact three times in a row to spit out the entire contents of its extradimensional storage; the target doesn't have to take these actions all in the same turn, but if it takes any other actions in between, it has to start over. The items eject into the target's space, possibly spilling out into adjacent spaces if there is too much to fit.\n\nWhen the spell ends or the target falls unconscious, the contents of the extradimensional storage are disgorged in a riotous spew, landing in the nearest unoccupied space, a bit wet but otherwise unharmed.\n\nHeightened (5th) The duration increases to 8 hours","source":{"provider":"PAIZO","sourceId":"F9mA2Bg27QKniIdv","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.bracing-tendrils","name":"Bracing Tendrils","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","force","manipulate"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Visible tendrils of force anchor your body to the ground, preventing unwanted movement. Whenever you're on the ground and a creature or effect attempts to forcibly move you from your space, you can use your spell DC in place of your Fortitude DC as the DC of the check to move you. If a creature wouldn't normally need a check to move you, it must succeed at an appropriate check (usually an Athletics check for physical movement) against your spell DC or you are unmoved; if an effect wouldn't normally need a check to move you, it must counteract bracing tendrils or you are unmoved. When a creature fails to move you in this way, you can choose to have the tendrils lash back and push them 5 feet away from you.\n\nWhile the tendrils anchor you in place when you come to a stop, they uproot easily to cooperate with your own voluntary movement, so you can still move freely while under the effect of the spell.","source":{"provider":"PAIZO","sourceId":"NeoRkU7C4BIz8fUM","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.burglars-blind","name":"Burglar's Blind","kind":"SPELL","rank":3,"rarity":"RARE","traits":["illusion","manipulate","subtle"],"traditions":["OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"1 willing creature","area":null},"duration":{"text":"10 minutes","sustained":true},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"The only thing thieves love more than being silent and stealthy is the piles of gold they win with that silence and stealth. You mask the target with multiple illusions combined in a perfect mix, affecting them with both the and spells. If the target takes a hostile action, burglar's blind and both the spells it grants end after the hostile action is completed.\nHeightened (5th) You can target up to 5 willing creatures. The spells end for all targets if any one of them takes a hostile action.","source":{"provider":"PAIZO","sourceId":"UkXTcJAeTOF2inPy","book":"Pathfinder NPC Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.butterfly-bender","name":"Butterfly Bender","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"2 hours"},"cost":"Alcohol worth a total of 20 gp × the ritual level"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Medicine (trained)","secondaryChecks":"Diplomacy","secondaryCasters":2},"description":"Sometimes, the problems in your life are too oppressive. Sometimes, you have a case you need to crack and you have no idea where to start. When you've exhausted all options and willpower, you might as well just get drunk and call it a night. The butterfly bender is a ritual to kill two birds with one stone. By twisting fate around a session of hard drinking, you and a small party (no more than five people) suspend judgment, memory, and even consciousness as you all hurl yourselves into the arms of destiny and politely ask for a favor. You all get blackout drunk and, if all goes according to plan, you'll wake up with some progress upon a quest you've all undertaken—hopefully, without too much collateral damage.\n\nThe participants of the ritual wake up the next day with some of the following, determined by the results of the ritual. Any options that aren't chosen are temporarily lost to you.\n- Your dignity.\n- A common item that has the consumable trait of a level no higher than that of the ritual, which might be useful for an upcoming challenge. If lost, you misplace all of your currently carried items—including keys to where your equipment might be stored. With a modicum of effort, you recover your items within 1 day.\n- A new friend or connection, as though you'd succeeded at a Diplomacy check to with a relevant NPC up to the ritual's level. If this is one of things lost, an existing friend refuses to speak to you for 1 day.\n- A useful piece of information, as though you'd succeeded at a Diplomacy check to Gather Information. If lost, you take a –4 status penalty to your next check to Recall Knowledge.\n- A convenient opportunity of the GM's choice. If there's no immediately relevant opportunity, you find an opportunity to at the ritual's level + 1. If lost, the result of your next attempt to Earn Income is one degree of success worse.\nCritical Success Pick two options from the above list. The GM then gives you a bonus 3rd option of their choice.\n\nSuccess Pick two options from the above list.\n\nFailure Pick one option from the above list.\n\nCritical Failure Pick two options from the above list. The GM gives you one of them.","source":{"provider":"PAIZO","sourceId":"wneYzMFUWreyqWHD","book":"Pathfinder Lost Omens Tian Xia Character Guide","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cascade-countermeasure","name":"Cascade Countermeasure","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["focus","magus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":1},"requirements":"You're benefitting from Arcane Cascade"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"until the Arcane Cascade stance ends","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You quickly adjust your to offer magical protection. You gain resistance 5 against damage from spells. As normal, using Arcane Cascade again means you've ended the stance, and the spell ends.\n\nHeightened (+3) The resistance increases by 5.","source":{"provider":"PAIZO","sourceId":"rtisvvvhkpZPdgXc","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.casters-imposition","name":"Caster's Imposition","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","curse","manipulate"],"traditions":["ARCANE","DIVINE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"NONE"},"target":"1 creature within 60 feet","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"A magical interference prevents the target from contributing to any form of cooperative spellcasting. On a failed save, the target can't participate in any ritual unless they can cast the ritual alone, and they can't access any spells provided by a coven or similar cooperative ability.\n\nHeightened (4th) Increase the duration to 1 hour.\n\nHeightened (5th) Increase the duration to 1 day.","source":{"provider":"PAIZO","sourceId":"mriIWoSDtJTJIBjX","book":"Pathfinder #182: Graveclaw","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cave-fangs","name":"Cave Fangs","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","earth","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"area":{"shape":"BURST","feet":20}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"1aOzFUJQMCR1aabW","formula":"6d6","damageType":"piercing","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"1aOzFUJQMCR1aabW":"2d6"}},"counteraction":false,"ritual":null,"description":"Sharp flowstone formations protrude from the ground and ceiling, dealing 6d6 piercing damage to creatures in the area with a basic Reflex save. Densely packed with protrusions, the area becomes difficult terrain for the duration. The protrusions turn to dust when the spell ends. You can Dismiss the spell.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"KEagmnwgsSbGmkme","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.censure-falsehoods","name":"Censure Falsehoods","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","curse","focus","hex","manipulate","witch"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You call on your patron to reprimand a creature that has attempted a Deception or Stealth check against you or an ally within the past month. You must be aware they did so. Whenever the target speaks, toads and serpents fall from their lips. The target attempts a Fortitude saving throw. The spell lasts as long as the target remains sickened by it.\nCritical Success A few animals fall from their lips, but they're otherwise unaffected.\n\nSuccess The target is Sickened 1.\n\nFailure The target is Sickened 2 and if they perform an action that has the auditory trait or attempt to Cast a Spell, they must succeed at a flat, or the action is disrupted as they choke on an animal.\n\nCritical Failure As failure, and if the target attempts a Deception or Stealth check, their sickened value increases by 1 (to a maximum of Sickened 4).","source":{"provider":"PAIZO","sourceId":"guHLRnTL1OBUYh0V","book":"Pathfinder Lost Omens Rival Academies","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.chilling-darkness","name":"Chilling Darkness","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["attack","cold","concentrate","darkness","manipulate","unholy"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"NONE"},"damage":[{"id":"0","formula":"5d6","damageType":"cold","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":true,"ritual":null,"description":"You shoot an utterly cold ray of darkness tinged with unholy energy. Make a ranged spell attack. The ray deals 5d6 cold damage. If the target has the holy trait, you deal an extra 5d6 spirit damage.\nCritical Success The target takes double damage.\n\nSuccess The target takes full damage.\n\nIf the ray passes through an area of magical light or targets a creature affected by magical light, chilling darkness attempts to counteract the light. If you need to determine whether the ray passes through an area of light, draw a line between yourself and the spell's target.\nHeightened (+1) The cold damage increases by 2d6, and the spirit damage against holy creatures increases by 2d6.","source":{"provider":"PAIZO","sourceId":"sRfSBHWHdbIa0aGc","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.circle-of-protection","name":"Circle of Protection","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"TOUCH"},"area":{"shape":"EMANATION","feet":10,"text":"10-foot emanation centered on the touched creature"}},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You ward a creature and those nearby against a specified alignment. Choose chaotic, evil, good, or lawful; this spell gains the opposing trait. Creatures in the area gain a +1 status bonus to AC against attacks by creatures of the chosen alignment and to saves against effects from such creatures. This bonus increases to +3 against effects from such creatures that directly control the target and attacks made by summoned creatures of the chosen alignment. Summoned creatures of the chosen alignment can't willingly enter the area without succeeding at a Will save; repeated attempts use the first save result.\n\nHeightened (4th) The duration increases to 1 hour.","source":{"provider":"PAIZO","sourceId":"mpGCMTldMVa0pWYs","book":"Pathfinder Core Rulebook","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.claim-curse","name":"Claim Curse","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate"],"traditions":["DIVINE","OCCULT"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TOUCH"},"target":"1 creature affected by a curse","area":null},"duration":{"text":"5 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"By burning threads of fate around a target and then retying them to yourself instead, you temporarily draw their curse to you and offer them brief succor from the worst of its effects. Choose a curse affecting the target that you don't already have. For 5 minutes, you are affected by the curse (at the same stage as the target, if applicable), and the target isn't. When the duration ends, the curse's effects return to the target as normal.","source":{"provider":"PAIZO","sourceId":"5OcZ3HBkrRFhSWCz","book":"Pathfinder Secrets of Magic","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.clairaudience","name":"Clairaudience","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","scrying"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":500},"area":null},"duration":{"text":"10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You create an floating ear at a location within range (even if it's outside your line of sight or line of effect). It can't move, but you can hear through the ear as if using your normal auditory senses.","source":{"provider":"PAIZO","sourceId":"HXhWYJviWalN5tQ2","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cloud-dragons-cloak","name":"Cloud Dragon's Cloak","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["air","manipulate"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"REACTION"}},"targeting":{"range":{"kind":"DISTANCE","feet":60},"target":"the creature targeted by the attack","area":null},"duration":{"text":"1 round","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Trigger You or an ally in range is targeted by a ranged attack.\n\nA cloud of mist enshrouds the target, appearing much like the deflecting clouds created by cloud dragons. The target is treated as for the purposes of resolving the triggering attack (so normally the attacker must succeed at a flat to target it) and all ranged attacks against it for the duration.","source":{"provider":"PAIZO","sourceId":"D5ZAWGqxml5xOiZb","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.combustion","name":"Combustion","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","fire","focus","manipulate"],"traditions":[],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":120},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"0","formula":"4d8","damageType":"fire","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"1d8"}},"counteraction":false,"ritual":null,"description":"You ignite a creature in lasting flames. The fire deals 4d8 fire damage and 2d6[persistent,fire] damage to the creature, which must attempt a Fortitude save.\n\nCritical Success The creature is unaffected.\n\nSuccess The creature takes half damage and takes no persistent damage.\n\nFailure The creature takes full damage, as well as full persistent damage.\n\nCritical Failure The creature takes double damage, as well as double persistent damage.\n\nHeightened (+1) Increase the initial damage by 1d8 and the persistent damage by 1d6[fire].","source":{"provider":"PAIZO","sourceId":"Z3kJty995FkrsZRb","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.conjured-conveyance","name":"Conjured Conveyance","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","manipulate","plant","wood"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"1 hour","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure an intricate vehicle, carved entirely from wood, to serve as a method of conveyance. The vehicle appears in an unoccupied area of your choice within range. The vehicle can be piloted using Arcana, Driving Lore, or Nature skill checks. The DC to pilot the vehicle and the DC of the vehicle's collision are equal to your spell DC. The vehicle's remaining statistics are presented below.\n\nWhen you Cast this Spell, choose whether to create a Large skiff, a Large wagon, or a Medium cycle. With the GM's permission, you might instead summon a different vehicle of your choice with a maximum level of 1; this vehicle must be made primarily of plant matter, have common rarity, and be Large or smaller.\n- Large Skiff—Space 15 feet long, 5 feet wide, 3 feet high; Crew 1 pilot; Passengers 3; Speed swim 30 feet (magical)\n\n- Large Wagon—Space 10 feet long, 10 feet wide, 7 feet high; Crew 1 pilot; Passengers 3; Speed 35 feet (magical)\n\n- Medium Cycle—Space 5 feet long, 3 feet wide, 3 feet high; Crew 1 pilot; Passengers 0; Speed 40 feet (magical)\n\nAC 13; Fortitude +8\n\nHardness 5, HP 40 (BT 20); Immunities critical hits, object immunities, precision damage; Weaknesses fire 5, slashing 5\n\nCollision 2d6\nHeightened (+1) The vehicle's AC increases by 2, Fortitude bonus increases by 2, Hardness increases by 1, HP increases by 20, and the collision damage increases by [[/r 1d6]]. In addition, the maximum level of vehicle you can summon with GM permission increases by 2. The duration increases by 1 hour.","source":{"provider":"PAIZO","sourceId":"FQd6Jc3CU6wiS2U7","book":"Pathfinder #203: Shepherd of Decay","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.consecrate-flesh","name":"Consecrate Flesh","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","good","manipulate"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"target":"self","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"INTERVAL","everyRanks":3,"damage":{}},"counteraction":false,"ritual":null,"description":"Through the strength of your faith, your body becomes infused with holy energy. You have weakness 5 to unholy. Any creature that touches or damages you with an unarmed attack or non-reach melee weapon takes 1d6 spirit damage. Your unarmed attacks deal an additional 1 spirit damage. Your healing spells that restore Hit Points restore an additional 1d4 Hit Points when you initially cast them; as normal, if your healing spell restores Hit Points more than once, grants fast healing, or the like, the additional Hit Points still only apply once.\n\nHeightened (+3) Creatures touching you take 1d6 additional spirit damage, your unarmed Strikes deal 1 additional spirit damage, your healing spells restore 1d4 more additional Hit Points, and your weakness to unholy increases by 5.","source":{"provider":"PAIZO","sourceId":"DgNOpb8H9MTAu9KL","book":"Pathfinder Lost Omens Knights of Lastwall","license":"OGL","remaster":false},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.contact-friends","name":"Contact Friends","kind":"RITUAL","rank":3,"rarity":"UNCOMMON","traits":[],"traditions":[],"casting":{"time":{"kind":"LONG","text":"1 hour"},"cost":"incense worth 50 gp"},"targeting":{"range":{"kind":"NONE"},"area":null},"duration":{"text":"up to 10 minutes","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":{"primaryCheck":"Arcana or Occultism (expert)","secondaryChecks":"Survival","secondaryCasters":0},"description":"You meditate for a quiet moment before your mind seeks out others whom you have befriended, as well as friends of any of the secondary casters. The ritual projects your mind to a blank space where you see one or more friends from your past. Once there, you can ask each friend a single question. If more than one friend is present, you can ask each one a different question. These friends aren't compelled to answer you honestly or answer at all, but those who are your friends are likely to help you if they can, barring special situations.\n\nCritical Success You contact up to three close friends of yourself or any of the secondary casters, and the friends attempt to help you with their knowledge. They each answer one of your questions, as described above.\n\nSuccess As critical success, but your mind reaches one friend, instead of three.\n\nFailure Your mind reaches three friends you've made in the past, but each of them gives you a useless fact. None of these facts help with your situation at all.\n\nCritical Failure Your mind freezes. You saw something that terrified you to your core, leaving you and all other casters Stupefied 3 for 1 day.","source":{"provider":"PAIZO","sourceId":"9vDmTCHyAWdWWPIs","book":"Pathfinder Dark Archive (Remastered)","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.coral-scourge","name":"Coral Scourge","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","incapacitation","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"Barnacles, coral, and other rough aquatic creatures grow on the target's body, getting in between their joints and stiffening their movement. This impedes the target's movement depending on the result of its saving throw.\n\nCritical Success The target is unaffected.\n\nSuccess The target is Clumsy 1. The target can Interact to scrape the coral growths from its body, decreasing the clumsy condition to 0 and ending the spell.\n\nFailure The target is Clumsy 2. Each round at the beginning of its turn, the target becomes clumsy 1 or increases its clumsy condition by 1, to a maximum of 4. The target can Interact to scrape the coral growths from its body, decreasing the clumsy condition to 0 and ending the spell. If the target's clumsy condition caused by coral scourge reaches 4, the growths spread to cover the target's entire body, and the target becomes .\n\nCritical Failure As failure, but when the target Interacts to scrape the coral growths from its body, it reduces its clumsy condition by 1, instead of decreasing it to 0, and decreasing the clumsy condition to 0 doesn't end the spell.","source":{"provider":"PAIZO","sourceId":"ZIk1EYbG6l4JuUkO","book":"Pathfinder Rage of Elements","license":"OGL","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cordyceps-command","name":"Cordyceps Command","kind":"SPELL","rank":3,"rarity":"UNCOMMON","traits":["concentrate","fungus","incapacitation","manipulate","poison"],"traditions":["PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"TEXT","text":"30"},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You conjure a mote of cordyceps spores uniquely tailored to the target before whisking it at them. When you Cast this Spell, choose one of the following behaviors that the fungus compels: ascend, consume, descend, or lure. While the target is controlled by the cordyceps toxin's stage 3 effects, it performs that behavior. This control might include risky behavior (such as climbing down a precarious cliff or weaving between armed foes), but it doesn't compel outright lethal actions (such as leaping off the top of that same cliff). If the behavior directly leads to harm (such as falling off the cliff) or hostile actions (such as being attacked by creatures that can now reach the descending creature), the target gains a +4 bonus to their next saving throw against the poison.\n\nAscend: The creature tries to reach higher altitudes by any reasonable means, such as Climbing, seeking stairs, or even stacking debris to jump atop of in an attempt to be as high up as possible.\n\nConsume: The creature greedily eats or drinks whatever is nearby, using actions to draw and consume elixirs, food, or other consumable items. If the creature has a jaws Strike, fangs Strike, or similar unarmed Strike, the creature can instead chase after and use that Strike against edible targets. If no other food or drink is accessible, the creature attempts to steal or seek nearby nutrition.\n\nDescend: The creature tries to reach lower altitudes by any reasonable means, such as Climbing, descending while flying, or even falling and attempting to burrow into the ground.\n\nLure: The creature moves toward an exposed location and attempts to get bystanders' attention, such as by gesticulating, Performing, or igniting light sources. The target is while controlled in this way.\nSuccess The target is unaffected.\n\nFailure The target is afflicted with cordyceps toxin at stage 1.\n\nCritical Failure The target is afflicted with cordyceps toxin at stage 2.\nCordyceps Toxin (poison)\n\nSaving Throw fortitude;\n\nMaximum Duration 6 rounds\n\nStage 1 Stupefied 1 (1 round)\n\nStage 2 (1 round)\n\nStage 3 (1 round)","source":{"provider":"PAIZO","sourceId":"ADwX87fWrpB8cQ5Q","book":"Pathfinder #203: Shepherd of Decay","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["RANGE_NOT_STRUCTURED","NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.cozy-cabin","name":"Cozy Cabin","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","wood"],"traditions":["ARCANE","OCCULT"],"casting":{"time":{"kind":"LONG","text":"1 minute"}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"area":null},"duration":{"text":"12 hours","sustained":false},"defense":{"kind":"NONE"},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You shape a cabin 20 feet on each side and 10 feet high. This cabin has the structure trait and the same restrictions as magic items that create structures. The walls of the hut are simple and wooden, with small, square glass windows, and it has one wooden door. It doesn't include its own lock, but it has a fastener to which a lock can be applied.\n\nThe interior contains three cots, one chamber pot, and a small fireplace holding a magical fire. The interior is lit with a small magical light that you can light or extinguish at will using a Sustain action. The climate inside the hut is comfortable and allows creatures inside it to withstand most hostile weather conditions, but incredible heat or cold, powerful storms, and winds of hurricane force or greater destroy the hut. Other creatures can freely enter and exit the hut without damaging it, but if you exit the hut, the spell ends. You can Dismiss the spell.","source":{"provider":"PAIZO","sourceId":"mwPfoYfVGSMAaUec","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}},{"id":"pf2e.spell.crashing-wave","name":"Crashing Wave","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","water"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"NONE"},"area":{"shape":"CONE","feet":30}},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"REFLEX","basic":true},"damage":[{"id":"0","formula":"6d6","damageType":"bludgeoning","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You summon a crashing wave that sweeps away from you. You deal 6d6 bludgeoning damage to creatures in the area. The water also extinguishes non-magical fires in the area.\n\nHeightened (+1) The damage increases by 2d6.","source":{"provider":"PAIZO","sourceId":"T4QKmtYPeCgYxVGe","book":"Pathfinder Player Core 2","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.crisis-of-faith","name":"Crisis of Faith","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","manipulate","mental"],"traditions":["DIVINE"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"","sustained":false},"defense":{"kind":"SAVE","statistic":"WILL","basic":false},"damage":[{"id":"0","formula":"6d6","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"0":"2d6"}},"counteraction":false,"ritual":null,"description":"You assault the target's faith, riddling the creature with doubt and mental turmoil that deal 6d6 mental damage, or 6d8 mental damage if it can cast divine spells. The effects are determined by its Will save.\n\nTo many deities, casting this spell on a follower of your own deity without significant cause is anathema.\n\nCritical Success The target is unaffected.\n\nSuccess The target takes half damage.\n\nFailure The target takes full damage; if the target can cast divine spells, it's Stupefied 1 for 1 round.\n\nCritical Failure The target takes double damage, is Stupefied 1 for 1 round, and can't cast divine spells for 1 round.\n\nHeightened (+1) The damage increases by 2d6 (or by 2d8 if the target is a divine spellcaster).","source":{"provider":"PAIZO","sourceId":"3x6eUCm17n6ROzUa","book":"Pathfinder Player Core","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.croak-voice","name":"Croak Voice","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","curse","manipulate","morph"],"traditions":["ARCANE","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":2}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 creature","area":null},"duration":{"text":"1 minute","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[{"id":"eJfn85qIm5CZi3Au","formula":"2d10","damageType":"mental","kind":"DAMAGE","applyAbilityModifier":false}],"heightening":{"kind":"INTERVAL","everyRanks":1,"damage":{"eJfn85qIm5CZi3Au":"1d10"}},"counteraction":false,"ritual":null,"description":"You cause the target creature's vocal chords to swell like those of a frog. The target must attempt a Fortitude save.\n\nCritical Success The target is unaffected.\n\nSuccess The target's voice becomes hoarse, and speaking becomes painful. Whenever it uses an action that has the auditory trait or attempts to Cast a Spell that doesn't have the subtle trait, it must succeed at a flat or the action is lost. Once per round, the target can spend an Interact action to massage its throat, attempting a Fortitude save against your spell DC. On a success, the spell ends.\n\nFailure As success, but using an action with the auditory trait also deals 2d10 mental damage to the target as the sound of its distorted voice grates on its ears.\n\nCritical Failure As failure, but the damage for using an action with the auditory trait is doubled, and the target can't use an Interact action to attempt a Fortitude save to end the effect early.\n\nHeightened (+1) The damage for using an action with the auditory trait increases by 1d10.","source":{"provider":"PAIZO","sourceId":"zVfTMpkXJDRESkl5","book":"Pathfinder Howl of the Wild","license":"ORC","remaster":true},"automation":{"status":"SUPPORTED","reasons":[]}},{"id":"pf2e.spell.cup-of-dust","name":"Cup of Dust","kind":"SPELL","rank":3,"rarity":"COMMON","traits":["concentrate","curse","manipulate"],"traditions":["ARCANE","OCCULT","PRIMAL"],"casting":{"time":{"kind":"ACTIONS","actions":3}},"targeting":{"range":{"kind":"DISTANCE","feet":30},"target":"1 living creature","area":null},"duration":{"text":"1 day","sustained":false},"defense":{"kind":"SAVE","statistic":"FORTITUDE","basic":false},"damage":[],"heightening":{"kind":"NONE"},"counteraction":false,"ritual":null,"description":"You curse the target with a thirst no drink can quench. You can Dismiss the spell. The target must attempt a Fortitude save.\nCritical Success The creature is unaffected and is temporarily immune for 1 hour.\n\nSuccess The creature is for 1 round.\n\nFailure The creature is immediately afflicted by thirst as if it hadn't had a drink in days. It becomes Fatigued and takes 1d4 damage each hour that can't be healed until it quenches its thirst. No amount of drinking can quench the creature's thirst during the spell's duration.\n\nCritical Failure As failure but the creature takes 2d4 damage each hour.\nHeightened (+3) The thirst becomes more unbearable, increasing the damage each hour by 1d4, or by 2d4 on a critical failure.","source":{"provider":"PAIZO","sourceId":"10siFBMF4pIDhVmf","book":"Pathfinder Lost Omens Divine Mysteries","license":"ORC","remaster":true},"automation":{"status":"MANUAL","reasons":["NO_STRUCTURED_DAMAGE_OR_HEALING"]}}]
